---
import type { IconProps } from "./types";

const {
	icon,
	class: className = "",
	style = "",
	size = "md",
	color,
	fallback = "●",
	loading = "lazy",
} = Astro.props as IconProps;

const sizeClasses = {
	xs: "text-xs",
	sm: "text-sm",
	md: "text-base",
	lg: "text-lg",
	xl: "text-xl",
	"2xl": "text-2xl",
};

const sizeClass = sizeClasses[size] || sizeClasses.md;
const colorStyle = color ? `color: ${color};` : "";
const combinedStyle = `${colorStyle}${style}`;
const combinedClass = `${sizeClass} ${className}`.trim();

const iconId = `icon-${Math.random().toString(36).substring(2, 9)}`;
---

<span
	class={`inline-flex items-center justify-center ${combinedClass}`}
	style={combinedStyle}
	data-icon-container={iconId}
>
	<span class="icon-loading animate-pulse opacity-50" data-loading-indicator>
		{fallback}
	</span>

	<iconify-icon
		icon={icon}
		class="icon-content opacity-0 transition-opacity duration-200"
		data-icon-element
		loading={loading}></iconify-icon>
</span>

<script is:inline define:vars={{ iconId, icon }}>
	(function () {
		const container = document.querySelector(
			`[data-icon-container="${iconId}"]`,
		);
		if (!container) {
			return;
		}

		const loadingIndicator = container.querySelector(
			"[data-loading-indicator]",
		);
		const iconElement = container.querySelector("[data-icon-element]");

		if (!loadingIndicator || !iconElement) {
			return;
		}

		function checkIconLoaded() {
			const hasContent =
				iconElement.shadowRoot &&
				iconElement.shadowRoot.children.length > 0;

			if (hasContent) {
				showIcon();
				return true;
			}
			return false;
		}

		function showIcon() {
			loadingIndicator.style.display = "none";
			iconElement.classList.remove("opacity-0");
			iconElement.classList.add("opacity-100");
		}

		function showLoading() {
			loadingIndicator.style.display = "inline-flex";
			iconElement.classList.remove("opacity-100");
			iconElement.classList.add("opacity-0");
		}

		showLoading();

		iconElement.addEventListener("load", () => {
			showIcon();
		});

		iconElement.addEventListener("error", () => {
			console.warn(`Failed to load icon: ${icon}`);
		});

		if (window.MutationObserver) {
			const observer = new MutationObserver(() => {
				if (checkIconLoaded()) {
					observer.disconnect();
				}
			});

			observer.observe(iconElement, {
				childList: true,
				subtree: true,
				attributes: true,
			});

			setTimeout(() => {
				observer.disconnect();
				if (!checkIconLoaded()) {
					console.warn(`Icon load timeout: ${icon}`);
				}
			}, 5000);
		}

		setTimeout(() => {
			checkIconLoaded();
		}, 100);
	})();
</script>

<style>
	.icon-loading {
		min-width: 1em;
		min-height: 1em;
		display: inline-flex;
		align-items: center;
		justify-content: center;
	}

	.icon-content {
		display: inline-flex;
		align-items: center;
		justify-content: center;
	}

	[data-icon-container] {
		position: relative;
		display: inline-flex;
		align-items: center;
		justify-content: center;
		min-width: 1em;
		min-height: 1em;
	}

	[data-icon-container] .icon-loading,
	[data-icon-container] .icon-content {
		position: absolute;
		top: 0;
		left: 0;
		width: 100%;
		height: 100%;
	}
</style>

---
interface Props {
	id?: string;
	src: string;
	class?: string;
	alt?: string;
	position?: string;
	basePath?: string;
	loading?: "eager" | "lazy";
	fetchpriority?: "high" | "low" | "auto";
	widths?: number[];
	sizes?: string;
}

import { Image as AstroImage } from "astro:assets";

import { url } from "../../../utils/url-utils";

const {
	id,
	src,
	alt,
	position = "center",
	basePath = "/",
	loading = "lazy",
	fetchpriority,
	widths,
	sizes,
} = Astro.props;
const className = Astro.props.class;

const isLocal = !(
	src.startsWith("/") ||
	src.startsWith("http") ||
	src.startsWith("https") ||
	src.startsWith("data:")
);
const isPublic = src.startsWith("/");

// TODO temporary workaround for images dynamic import
// https://github.com/withastro/astro/issues/3373
// biome-ignore lint/suspicious/noImplicitAnyLet: <check later>
let img: ImageMetadata | undefined;
if (isLocal) {
	const files = import.meta.glob<ImageMetadata>("../../../**", {
		import: "default",
	});
	// 使用字符串操作替代 path.normalize 和 path.join
	const normalizedPath = normalizePath(`../../../${basePath}/${src}`);
	const file = files[normalizedPath];
	if (!file) {
		console.error(
			`\n[ERROR] Image file not found: ${normalizedPath.replace("../../../", "src/")}`,
		);
	} else {
		img = await file();
	}
}

const imageClass = "w-full h-full object-cover";
const imageStyle = `object-position: ${position}`;

// 检查是否是 Bilibili 图片
const isBilibiliImage = !isLocal && src.includes("hdslb.com");
// 对于外部图片（特别是 Bilibili），需要设置 referrerpolicy 避免 403 错误
const referrerPolicy = !isLocal && isBilibiliImage ? "no-referrer" : undefined;

// 简单的路径规范化函数，替代 path.normalize
function normalizePath(path: string): string {
	// 将反斜杠替换为正斜杠
	path = path.replace(/\\/g, "/");

	// 处理 ../ 和 ./
	const parts = path.split("/");
	const result: string[] = [];

	for (const part of parts) {
		if (part === ".." && result.length > 0 && result[result.length - 1] !== "..") {
			result.pop();
		} else if (part !== "." && part !== "") {
			result.push(part);
		}
	}

	// 保留开头的 ../
	const prefixParts: string[] = [];
	for (const part of parts) {
		if (part === "..") {
			prefixParts.push(part);
		} else if (part !== "." && part !== "") {
			break;
		}
	}

	return [...prefixParts, ...result].join("/");
}
---

<div id={id} class:list={[className, "overflow-hidden relative"]}>
	<div
		class="transition absolute inset-0 dark:bg-black/10 bg-opacity-50 pointer-events-none"
	>
	</div>
	{
		isLocal && img && (
			<AstroImage
				src={img}
				alt={alt || ""}
				class={imageClass}
				style={imageStyle}
				loading={loading}
				fetchpriority={fetchpriority}
				widths={widths}
				sizes={sizes}
			/>
		)
	}
	{
		!isLocal && (
			<img
				src={isPublic ? url(src) : src}
				alt={alt || ""}
				class={imageClass}
				style={imageStyle}
				loading={loading}
				referrerpolicy={referrerPolicy}
				crossorigin={isBilibiliImage ? "anonymous" : undefined}
				fetchpriority={fetchpriority}
			/>
		)
	}
</div>

---
import { commentConfig } from "@/config";

interface Props {
	path: string;
}

const config = {
	...commentConfig.twikoo,
	el: "#tcomment",
	path: Astro.props.path,
};
---

<div id="twikoo-container" class="twikoo-container">
	<div id="tcomment"></div>
</div>

<script is:inline define:vars={{ config }}>
	(function () {
		const TWIKOO_CONTAINER_ID = "twikoo-container";
		const SCROLL_PROTECTION_URL = "/scroll-protection.js";
		const TWIKOO_SCRIPT_URL = "/assets/js/twikoo.all.min.js";
		const ROOT_MARGIN = "200px";

		let observer = null;
		let twikooLoaded = false;

		function getCurrentPath() {
			const pathname = window.location.pathname;
			return pathname.endsWith("/") && pathname.length > 1
				? pathname.slice(0, -1)
				: pathname;
		}

		function createTwikooConfig() {
			return {
				...config,
				path: getCurrentPath(),
				el: "#tcomment",
			};
		}

		async function loadScrollProtection() {
			return new Promise((resolve, reject) => {
				if (document.getElementById("scroll-protection-loaded")) {
					resolve();
					return;
				}
				const script = document.createElement("script");
				script.src = SCROLL_PROTECTION_URL;
				script.onload = () => {
					const marker = document.createElement("div");
					marker.id = "scroll-protection-loaded";
					document.body.appendChild(marker);
					resolve();
				};
				script.onerror = reject;
				document.head.appendChild(script);
			});
		}

		async function loadTwikooScript() {
			if (
				twikooLoaded ||
				document.getElementById("twikoo-script-loaded")
			) {
				return;
			}
			await loadScrollProtection();
			return new Promise((resolve, reject) => {
				const script = document.createElement("script");
				script.id = "twikoo-script-loaded";
				script.src = TWIKOO_SCRIPT_URL;
				script.async = true;
				script.onload = () => {
					twikooLoaded = true;
					resolve();
				};
				script.onerror = reject;
				document.head.appendChild(script);
			});
		}

		async function initTwikoo() {
			const commentEl = document.getElementById("tcomment");
			if (!commentEl) {
				return;
			}

			try {
				await loadTwikooScript();

				if (typeof twikoo === "undefined") {
					console.warn("[Twikoo] 脚本加载失败");
					return;
				}

				commentEl.innerHTML = "";
				const dynamicConfig = createTwikooConfig();
				await twikoo.init(dynamicConfig);
			} catch (error) {
				console.error("[Twikoo] 初始化失败:", error);
			}
		}

		function cleanup() {
			if (observer) {
				observer.disconnect();
				observer = null;
			}
			if (window.swup?.hooks) {
				window.swup.hooks.off("content:replace", initTwikoo);
			}
		}

		function setupLazyLoad() {
			const container = document.getElementById(TWIKOO_CONTAINER_ID);
			if (!container) {
				return;
			}

			observer = new IntersectionObserver(
				(entries) => {
					if (entries[0].isIntersecting) {
						observer.disconnect();
						observer = null;
						initTwikoo();
					}
				},
				{ rootMargin: ROOT_MARGIN },
			);

			observer.observe(container);
		}

		function setupSwupHooks() {
			if (window.swup?.hooks) {
				window.swup.hooks.on("content:replace", () => {
					setTimeout(setupLazyLoad, 200);
				});
			} else {
				document.addEventListener(
					"swup:enable",
					() => {
						if (window.swup?.hooks) {
							window.swup.hooks.on("content:replace", () => {
								setTimeout(setupLazyLoad, 200);
							});
						}
					},
					{ once: true },
				);
			}
		}

		document.addEventListener("mizuki:page:loaded", () => {
			setupLazyLoad();
		});

		window.addEventListener("beforeunload", cleanup);

		if (document.readyState === "loading") {
			document.addEventListener("DOMContentLoaded", () => {
				setupLazyLoad();
				setupSwupHooks();
			});
		} else {
			setupLazyLoad();
			setupSwupHooks();
		}
	})();
</script>

<style>
	.twikoo-container {
		min-height: 200px;
	}
</style>

---
import type { Page } from "astro";
import { Icon } from "astro-icon/components";

import { url } from "../../utils/url-utils";

interface Props {
	page: Page;
	class?: string;
	style?: string;
}

const { page, style } = Astro.props;

const HIDDEN = -1;

const className = Astro.props.class;

const ADJ_DIST = 2;
const VISIBLE = ADJ_DIST * 2 + 1;

// for test
let count = 1;
let l = page.currentPage;
let r = page.currentPage;
while (0 < l - 1 && r + 1 <= page.lastPage && count + 2 <= VISIBLE) {
	count += 2;
	l--;
	r++;
}
while (0 < l - 1 && count < VISIBLE) {
	count++;
	l--;
}
while (r + 1 <= page.lastPage && count < VISIBLE) {
	count++;
	r++;
}

const pages: number[] = [];
if (l > 1) {
	pages.push(1);
}
if (l === 3) {
	pages.push(2);
}
if (l > 3) {
	pages.push(HIDDEN);
}
for (let i = l; i <= r; i++) {
	pages.push(i);
}
if (r < page.lastPage - 2) {
	pages.push(HIDDEN);
}
if (r === page.lastPage - 2) {
	pages.push(page.lastPage - 1);
}
if (r < page.lastPage) {
	pages.push(page.lastPage);
}

const getPageUrl = (p: number) => {
	if (p === 1) {
		return "/";
	}
	return `/${p}/`;
};
---

<div
	class:list={[className, "flex flex-row gap-3 justify-center"]}
	style={style}
>
	<a
		href={page.url.prev || ""}
		aria-label="上一页"
		class:list={[
			"btn-card overflow-hidden rounded-lg text-[var(--primary)] w-11 h-11",
			{ disabled: page.url.prev == undefined },
		]}
	>
		<Icon
			name="material-symbols:chevron-left-rounded"
			class="text-[1.75rem]"
		/>
	</a>
	<div
		class="bg-[var(--card-bg)] flex flex-row rounded-lg items-center text-neutral-700 dark:text-neutral-300 font-bold"
	>
		{
			pages.map((p) => {
				if (p == HIDDEN) {
					return (
						<Icon name="material-symbols:more-horiz" class="mx-1" />
					);
				}
				if (p == page.currentPage) {
					return (
						<div
							class="h-11 w-11 rounded-lg bg-[var(--primary)] flex items-center justify-center
                    font-bold text-white dark:text-black/70"
						>
							{p}
						</div>
					);
				}
				return (
					<a
						href={url(getPageUrl(p))}
						aria-label={`Page ${p}`}
						class="btn-card w-11 h-11 rounded-lg overflow-hidden active:scale-[0.85]"
					>
						{p}
					</a>
				);
			})
		}
	</div>
	<a
		href={page.url.next || ""}
		aria-label="下一页"
		class:list={[
			"btn-card overflow-hidden rounded-lg text-[var(--primary)] w-11 h-11",
			{ disabled: page.url.next == undefined },
		]}
	>
		<Icon
			name="material-symbols:chevron-right-rounded"
			class="text-[1.75rem]"
		/>
	</a>
</div>

---
import I18nKey from "@i18n/i18nKey";
import { i18n } from "@i18n/translation";

import PasswordModal from "./PasswordModal.svelte";

export interface Props {
	encryptedContent: string;
	hint?: string;
}

const { encryptedContent, hint = "" } = Astro.props;

const i18nUnlocking = i18n(I18nKey.passwordUnlocking);
const i18nIncorrect = i18n(I18nKey.passwordIncorrect);
const i18nDecryptionError = i18n(I18nKey.decryptionError);
const i18nUnlock = i18n(I18nKey.passwordUnlock);
const i18nPasswordRequired = i18n(I18nKey.passwordRequired);
const i18nPasswordDecryptRetry = i18n(I18nKey.passwordDecryptRetry);
---

<div id="password-protection">
	<PasswordModal client:load hint={hint} />
</div>

<div
	id="decrypted-content"
	class="decrypted-content w-full"
	style="display: none;"
>
</div>

<style>
	.decrypted-content {
		animation: fadeIn 0.3s ease-in-out;
	}

	@keyframes fadeIn {
		from {
			opacity: 0;
			transform: translateY(10px);
		}
		to {
			opacity: 1;
			transform: translateY(0);
		}
	}

	:global(#decrypted-content .table-wrapper) {
		overflow-x: auto !important;
		width: 100% !important;
	}

	:global(#decrypted-content table) {
		display: table !important;
		width: 100% !important;
	}

	:global(.encrypted-hidden) {
		display: none !important;
	}

	:global(.encrypted-hidden-wrapper.encrypted-hidden) {
		display: none !important;
	}
</style>

{}
<script
	is:inline
	define:vars={{
		encryptedContent,
		i18nUnlocking,
		i18nIncorrect,
		i18nDecryptionError,
		i18nUnlock,
		i18nPasswordRequired,
		i18nPasswordDecryptRetry,
	}}
>
	function showError(message) {
		const event = new CustomEvent("password:error", { detail: message });
		document.dispatchEvent(event);
	}

	function setLoading(loading) {
		const event = new CustomEvent("password:loading", { detail: loading });
		document.dispatchEvent(event);
	}

	function clearError() {
		const event = new CustomEvent("password:clear-error", {});
		document.dispatchEvent(event);
	}

	async function loadCryptoLibraries() {
		if (typeof CryptoJS === "undefined") {
			await new Promise((resolve, reject) => {
				const script = document.createElement("script");
				script.src = "/assets/js/crypto-js.min.js";
				script.onload = resolve;
				script.onerror = reject;
				document.head.appendChild(script);
			});
		}
	}

	async function attemptUnlock(inputPassword) {
		if (!inputPassword) {
			showError(i18nPasswordRequired);
			return;
		}

		setLoading(true);
		clearError();

		await loadCryptoLibraries();

		try {
			const decryptedBytes = CryptoJS.AES.decrypt(
				encryptedContent,
				inputPassword,
			);
			const decryptedString = decryptedBytes.toString(CryptoJS.enc.Utf8);

			if (
				!decryptedString ||
				!decryptedString.startsWith("MIZUKI-VERIFY:")
			) {
				showError(i18nIncorrect);
				sessionStorage.removeItem(
					"page-password-" + window.location.pathname,
				);
				setLoading(false);
				return;
			}

			const realContent = decryptedString.replace("MIZUKI-VERIFY:", "");
			const contentDiv = document.getElementById("decrypted-content");
			const protectionDiv = document.getElementById(
				"password-protection",
			);

			if (contentDiv) {
				contentDiv.innerHTML = realContent;

				const scripts = contentDiv.querySelectorAll("script");
				const scriptPromises = Array.from(scripts).map((script) => {
					return new Promise((resolve) => {
						const newScript = document.createElement("script");
						if (script.type) {
							newScript.type = script.type;
						}
						newScript.textContent = script.textContent;
						newScript.onload = resolve;
						newScript.onerror = resolve;
						script.parentNode?.replaceChild(newScript, script);
						if (!newScript.src) {
							resolve(undefined);
						}
					});
				});
				await Promise.all(scriptPromises);

				if (protectionDiv && protectionDiv.parentNode) {
					protectionDiv.remove();
				}
				contentDiv.style.display = "block";

				const shareComponent =
					document.getElementById("share-component");
				const licenseComponent =
					document.getElementById("license-component");
				if (shareComponent) {
					shareComponent.classList.remove("encrypted-hidden");
				}
				if (licenseComponent) {
					licenseComponent.classList.remove("encrypted-hidden");
				}

				sessionStorage.setItem(
					"page-password-" + window.location.pathname,
					inputPassword,
				);

				triggerPostDecryptUpdates();
			}
		} catch (error) {
			console.error(i18nDecryptionError, error);
			showError(i18nPasswordDecryptRetry);
		} finally {
			setLoading(false);
		}
	}

	function triggerPostDecryptUpdates() {
		setTimeout(async () => {
			if (window.hljs) {
				const contentDiv = document.getElementById("decrypted-content");
				if (contentDiv) {
					contentDiv.querySelectorAll("pre code").forEach((block) => {
						window.hljs.highlightElement(block);
					});
				}
			}

			const tocElement = document.querySelector("table-of-contents");
			if (tocElement && typeof tocElement.regenerateTOC === "function") {
				tocElement.regenerateTOC();
				tocElement.init();
			}

			if (typeof window.mobileTOCInit === "function") {
				window.mobileTOCInit();
			}

			if (typeof Fancybox !== "undefined" && Fancybox.bind) {
				Fancybox.unbind("[data-fancybox]");
				Fancybox.bind("[data-fancybox]", {});
			}

			if (window.location.hash) {
				const targetId = window.location.hash.substring(1);
				const targetElement = document.getElementById(targetId);
				if (targetElement) {
					targetElement.scrollIntoView({ behavior: "smooth" });
				}
			}

			const contentDiv = document.getElementById("decrypted-content");
			if (contentDiv) {
				const images = contentDiv.querySelectorAll("img");
				images.forEach((img) => {
					if (!img.complete) {
						img.addEventListener("load", () => {
							window.dispatchEvent(new Event("scroll"));
							window.dispatchEvent(new Event("resize"));
						});
					}
				});

				[0, 100, 300, 500, 1000, 2000].forEach((delay) => {
					setTimeout(() => {
						window.dispatchEvent(new Event("scroll"));
						window.dispatchEvent(new Event("resize"));
					}, delay);
				});
			}

			if (typeof window.renderMermaidDiagrams === "function") {
				await new Promise((resolve) => setTimeout(resolve, 100));
				window.renderMermaidDiagrams();
			}
		}, 50);
	}

	document.addEventListener("password:unlock", async (e) => {
		const detail = e.detail;
		if (detail && detail.password) {
			await attemptUnlock(detail.password);
		}
	});

	document.addEventListener("click", function (e) {
		const target = e.target;
		if (!target) {
			return;
		}

		const btn = target.closest(".copy-btn");

		if (btn) {
			const codeEle = btn.parentElement?.querySelector("code");

			if (codeEle) {
				let code = "";

				const lineElements = codeEle.querySelectorAll("span.line");
				if (lineElements.length > 0) {
					const lines = [];
					for (let i = 0; i < lineElements.length; i++) {
						lines.push(lineElements[i].textContent || "");
					}
					code = lines.join("\n");
				} else {
					const codeElements = codeEle.querySelectorAll(
						".code:not(summary *)",
					);
					if (codeElements.length > 0) {
						const lines = [];
						for (let i = 0; i < codeElements.length; i++) {
							lines.push(codeElements[i].textContent || "");
						}
						code = lines.join("\n");
					} else {
						code = codeEle.textContent || "";
					}
				}

				code = code.replace(/\n{3,}/g, (match) => {
					const emptyLineCount = match.length - 1;
					const resultEmptyLines = Math.ceil(emptyLineCount / 2);
					return "\n".repeat(resultEmptyLines + 1);
				});

				const copyToClipboard = async (text) => {
					try {
						await navigator.clipboard.writeText(text);
					} catch (clipboardErr) {
						console.error("Clipboard copy failed:", clipboardErr);
					}
				};

				copyToClipboard(code)
					.then(() => {
						const timeoutId = btn.getAttribute("data-timeout-id");
						if (timeoutId) {
							clearTimeout(parseInt(timeoutId));
						}

						btn.classList.add("success");

						const newTimeoutId = setTimeout(() => {
							btn.classList.remove("success");
						}, 1000);

						btn.setAttribute(
							"data-timeout-id",
							newTimeoutId.toString(),
						);
					})
					.catch((err) => {
						console.error("copy failed:", err);
					});
			}
		}
	});

	const savedPassword = sessionStorage.getItem(
		"page-password-" + window.location.pathname,
	);
	if (savedPassword) {
		attemptUnlock(savedPassword);
	}
</script>

/**
 * Decryption utilities for password-protected content
 *
 * Note: These functions are designed to run in the browser where CryptoJS
 * is available as a global variable after loading /assets/js/crypto-js.min.js
 */

import type { DecryptResult } from "../types/auth";

declare const CryptoJS: {
	AES: {
		decrypt: (
			encryptedContent: string,
			password: string,
		) => {
			toString: (encoding: typeof CryptoJS.enc.Utf8) => string;
		};
	};
	enc: { Utf8: unknown };
};

const CRYPTOJS_URL = "/assets/js/crypto-js.min.js";
const VERIFICATION_PREFIX = "MIZUKI-VERIFY:";

export async function loadCryptoLibraries(): Promise<void> {
	if (typeof CryptoJS === "undefined") {
		await new Promise<void>((resolve, reject) => {
			const script = document.createElement("script");
			script.src = CRYPTOJS_URL;
			script.onload = () => resolve();
			script.onerror = () => reject(new Error("Failed to load CryptoJS"));
			document.head.appendChild(script);
		});
	}
}

export function verifyCryptoLoaded(): boolean {
	return typeof CryptoJS !== "undefined";
}

export async function decryptContent(
	encryptedContent: string,
	password: string,
): Promise<DecryptResult> {
	if (!verifyCryptoLoaded()) {
		await loadCryptoLibraries();
	}

	if (!password) {
		return { success: false, content: null, error: "passwordRequired" };
	}

	try {
		const decryptedBytes = CryptoJS.AES.decrypt(encryptedContent, password);
		const decryptedString = decryptedBytes.toString(CryptoJS.enc.Utf8);

		if (
			!decryptedString ||
			!decryptedString.startsWith(VERIFICATION_PREFIX)
		) {
			return { success: false, content: null, error: "incorrect" };
		}

		const realContent = decryptedString.replace(VERIFICATION_PREFIX, "");
		return { success: true, content: realContent, error: null };
	} catch (error) {
		console.error("Decryption error:", error);
		return { success: false, content: null, error: "decryptionError" };
	}
}

export async function executeDecryptedScripts(
	contentDiv: HTMLElement,
): Promise<void> {
	const scripts = contentDiv.querySelectorAll("script");
	const scriptPromises = Array.from(scripts).map((script) => {
		return new Promise<void>((resolve) => {
			const newScript = document.createElement("script");
			if (script.type) {
				newScript.type = script.type;
			}
			newScript.textContent = script.textContent;
			newScript.onload = () => resolve();
			newScript.onerror = () => resolve();
			script.parentNode?.replaceChild(newScript, script);
			if (!newScript.src) {
				resolve();
			}
		});
	});
	await Promise.all(scriptPromises);
}

export function showShareComponents(): void {
	const shareComponent = document.getElementById("share-component");
	const licenseComponent = document.getElementById("license-component");
	if (shareComponent) {
		shareComponent.classList.remove("encrypted-hidden");
	}
	if (licenseComponent) {
		licenseComponent.classList.remove("encrypted-hidden");
	}
}

const SESSION_UNLOCKED_MARKER = "UNLOCKED";

export function savePassword(password: string): void {
	const key = "page-password-" + window.location.pathname;
	// Do not store cleartext secrets in Web Storage.
	// Preserve session "unlocked" state with a non-sensitive marker only.
	void password;
	sessionStorage.setItem(key, SESSION_UNLOCKED_MARKER);
}

export function getSavedPassword(): string | null {
	const key = "page-password-" + window.location.pathname;
	const storedValue = sessionStorage.getItem(key);
	return storedValue === SESSION_UNLOCKED_MARKER
		? SESSION_UNLOCKED_MARKER
		: null;
}

export function removeSavedPassword(): void {
	const key = "page-password-" + window.location.pathname;
	sessionStorage.removeItem(key);
}

export function triggerPostDecryptUpdates(): void {
	setTimeout(() => {
		highlightCode();
		regenerateTOC();
		initMobileTOC();
		bindFancybox();
		handleHashNavigation();
		triggerImageLoadEvents();
		triggerMermaidRender();
	}, 50);
}

function highlightCode(): void {
	if (window.hljs) {
		const contentDiv = document.getElementById("decrypted-content");
		if (contentDiv) {
			contentDiv.querySelectorAll("pre code").forEach((block) => {
				window.hljs!.highlightElement(block as HTMLElement);
			});
		}
	}
}

function regenerateTOC(): void {
	const tocElement = document.querySelector("table-of-contents") as
		| (HTMLElement & { init?: () => void; regenerateTOC?: () => void })
		| null;
	if (tocElement) {
		if (typeof tocElement.regenerateTOC === "function") {
			tocElement.regenerateTOC();
		}
		if (typeof tocElement.init === "function") {
			tocElement.init();
		}
	}
}

function initMobileTOC(): void {
	if (typeof window.mobileTOCInit === "function") {
		window.mobileTOCInit();
	}
}

function bindFancybox(): void {
	if (typeof Fancybox !== "undefined" && Fancybox.bind) {
		Fancybox.unbind("[data-fancybox]");
		Fancybox.bind("[data-fancybox]", {});
	}
}

function handleHashNavigation(): void {
	if (window.location.hash) {
		const targetId = window.location.hash.substring(1);
		const targetElement = document.getElementById(targetId);
		if (targetElement) {
			targetElement.scrollIntoView({ behavior: "smooth" });
		}
	}
}

function triggerImageLoadEvents(): void {
	const contentDiv = document.getElementById("decrypted-content");
	if (!contentDiv) {
		return;
	}

	const images = contentDiv.querySelectorAll("img");
	images.forEach((img) => {
		if (!img.complete) {
			img.addEventListener("load", () => {
				window.dispatchEvent(new Event("scroll"));
				window.dispatchEvent(new Event("resize"));
			});
		}
	});

	[0, 100, 300, 500, 1000, 2000].forEach((delay) => {
		setTimeout(() => {
			window.dispatchEvent(new Event("scroll"));
			window.dispatchEvent(new Event("resize"));
		}, delay);
	});
}

async function triggerMermaidRender(): Promise<void> {
	if (typeof window.renderMermaidDiagrams === "function") {
		await new Promise((resolve) => setTimeout(resolve, 100));
		window.renderMermaidDiagrams();
	}
}

/**
 * Password utility functions for encryption/decryption
 *
 * Note: These functions are designed to run in the browser where CryptoJS
 * is available as a global variable after loading /assets/js/crypto-js.min.js
 */

// Declare CryptoJS as a global variable
declare const CryptoJS: any;

/**
 * Decrypt content using AES
 */
export async function decryptContent(
	encryptedContent: string,
	password: string,
): Promise<string | null> {
	if (typeof CryptoJS === "undefined") {
		await loadCryptoLibraries();
	}

	try {
		const decryptedBytes = CryptoJS.AES.decrypt(encryptedContent, password);
		const decryptedString = decryptedBytes.toString(CryptoJS.enc.Utf8);

		// Verify the decrypted content has the expected prefix
		if (!decryptedString || !decryptedString.startsWith("MIZUKI-VERIFY:")) {
			return null;
		}

		return decryptedString.replace("MIZUKI-VERIFY:", "");
	} catch (error) {
		console.error("Decryption error:", error);
		return null;
	}
}

/**
 * Load CryptoJS library dynamically
 */
export async function loadCryptoLibraries(): Promise<void> {
	if (typeof CryptoJS === "undefined") {
		await new Promise((resolve, reject) => {
			const script = document.createElement("script");
			script.src = "/assets/js/crypto-js.min.js";
			script.onload = resolve;
			script.onerror = reject;
			document.head.appendChild(script);
		});
	}
}

