					name="material-symbols:help-outline"
					class="mr-2 text-[var(--primary)]"
				/>
				{
					t(
						`${prefix}WhatIs${prefix.charAt(0).toUpperCase() + prefix.slice(1)}`,
					)
				}
			</h2>
			<div class="text-75 space-y-3">
				<p>
					{
						t(
							`${prefix}WhatIs${prefix.charAt(0).toUpperCase() + prefix.slice(1)}Description`,
						)
					}
				</p>
				<ul class="list-disc list-inside space-y-1 ml-4">
					<li>{t(`${prefix}Benefit1`)}</li>
					<li>{t(`${prefix}Benefit2`)}</li>
					<li>{t(`${prefix}Benefit3`)}</li>
					<li>{t(`${prefix}Benefit4`)}</li>
				</ul>
				<p class="text-sm">
					{t(`${prefix}HowToUse`)}
				</p>
			</div>
		</div>
	</div>

	<script>
		const init = () => {
			const btn =
				document.getElementById("copy-rss-btn") ||
				document.getElementById("copy-atom-btn");
			if (btn) {
				btn.addEventListener("click", async function () {
					const url = this.getAttribute("data-url");
					if (!url) {
						return;
					}
					try {
						await navigator.clipboard.writeText(url);
						const originalText = this.textContent || "Copy Link";
						this.textContent = url.includes("rss")
							? "RSS link copied to clipboard!"
							: "Atom link copied to clipboard!";
						this.style.backgroundColor =
							"var(--success-color, #10b981)";

						setTimeout(() => {
							this.textContent = originalText;
							this.style.backgroundColor = "";
						}, 2000);
					} catch (err) {
						console.error("复制失败:", err);
						const originalText = this.textContent || "Copy Link";
						this.textContent =
							"Copy failed, please copy the link manually";
						setTimeout(() => {
							this.textContent = originalText;
						}, 2000);
					}
				});
			}
		};
		init();
		document.addEventListener("astro:after-swap", init);
	</script>
</MainGridLayout>

import { DEFAULT_SONG } from "../constants";
import type { Song } from "../types";

export interface AudioPlayerState {
	isPlaying: boolean;
	currentTime: number;
	duration: number;
	volume: number;
	isMuted: boolean;
	isLoading: boolean;
	currentSong: Song;
	autoplayFailed: boolean;
	willAutoPlay: boolean;
}

export function createAudioPlayerState(): AudioPlayerState {
	return {
		isPlaying: false,
		currentTime: 0,
		duration: 0,
		volume: 0.7,
		isMuted: false,
		isLoading: false,
		currentSong: DEFAULT_SONG,
		autoplayFailed: false,
		willAutoPlay: false,
	};
}

export function togglePlay(
	state: AudioPlayerState,
	audio: HTMLAudioElement | undefined,
) {
	if (!audio || !state.currentSong.url) {
		return;
	}
	if (state.isPlaying) {
		audio.pause();
	} else {
		audio.play().catch(() => {});
	}
}

export function toggleMute(state: AudioPlayerState) {
	state.isMuted = !state.isMuted;
}

export function handleLoadSuccess(
	state: AudioPlayerState,
	audio: HTMLAudioElement | undefined,
) {
	state.isLoading = false;
	if (audio?.duration && audio.duration > 1) {
		state.duration = Math.floor(audio.duration);
		state.currentSong = { ...state.currentSong, duration: state.duration };
	}

	if (state.willAutoPlay || state.isPlaying) {
		const playPromise = audio?.play();
		if (playPromise !== undefined) {
			playPromise.catch((error) => {
				console.warn("自动播放被拦截，等待用户交互:", error);
				state.autoplayFailed = true;
				state.isPlaying = false;
			});
		}
	}
}

export function handleLoadError(state: AudioPlayerState): {
	shouldContinue: boolean;
} {
	if (!state.currentSong.url) {
		return { shouldContinue: false };
	}
	state.isLoading = false;
	return { shouldContinue: state.isPlaying || state.willAutoPlay };
}

export function loadSong(state: AudioPlayerState, song: Song, autoPlay = true) {
	if (!song) {
		return;
	}
	if (song.url !== state.currentSong.url) {
		state.currentSong = { ...song };
		if (song.url) {
			state.isLoading = true;
		} else {
			state.isLoading = false;
		}
	}
	state.willAutoPlay = autoPlay;
}

export function handleUserInteraction(
	state: AudioPlayerState,
	audio: HTMLAudioElement | undefined,
) {
	if (state.autoplayFailed && audio) {
		const playPromise = audio.play();
		if (playPromise !== undefined) {
			playPromise
				.then(() => {
					state.autoplayFailed = false;
				})
				.catch(() => {});
		}
	}
}

import { STORAGE_KEY_VOLUME } from "../constants";
import type { AudioPlayerState } from "./useAudioPlayer";

export interface VolumeDragState {
	isVolumeDragging: boolean;
	isPointerDown: boolean;
	volumeBarRect: DOMRect | null;
	rafId: number | null;
}

export function createVolumeDragState(): VolumeDragState {
	return {
		isVolumeDragging: false,
		isPointerDown: false,
		volumeBarRect: null,
		rafId: null,
	};
}

export function loadVolumeFromStorage(state: AudioPlayerState) {
	try {
		if (typeof localStorage !== "undefined") {
			const savedVolume = localStorage.getItem(STORAGE_KEY_VOLUME);
			if (savedVolume !== null && !isNaN(parseFloat(savedVolume))) {
				state.volume = parseFloat(savedVolume);
			}
		}
	} catch (e) {
		console.warn("Failed to load volume settings from localStorage:", e);
	}
}

export function saveVolumeToStorage(state: AudioPlayerState) {
	try {
		if (typeof localStorage !== "undefined") {
			localStorage.setItem(STORAGE_KEY_VOLUME, state.volume.toString());
		}
	} catch (e) {
		console.warn("Failed to save volume settings to localStorage:", e);
	}
}

function updateVolumeLogic(
	clientX: number,
	dragState: VolumeDragState,
	volumeBar: HTMLElement | null,
	audio: HTMLAudioElement | undefined,
	audioPlayerState: AudioPlayerState,
) {
	if (!audio || !volumeBar) {
		return;
	}

	const rect = dragState.volumeBarRect || volumeBar.getBoundingClientRect();
	const percent = Math.max(
		0,
		Math.min(1, (clientX - rect.left) / rect.width),
	);
	audioPlayerState.volume = percent;
}

export function startVolumeDrag(
	event: PointerEvent,
	dragState: VolumeDragState,
	volumeBar: HTMLElement | null,
	audio: HTMLAudioElement | undefined,
	audioPlayerState: AudioPlayerState,
) {
	if (!volumeBar) {
		return;
	}
	event.preventDefault();

	dragState.isPointerDown = true;
	volumeBar.setPointerCapture(event.pointerId);

	dragState.volumeBarRect = volumeBar.getBoundingClientRect();
	updateVolumeLogic(
		event.clientX,
		dragState,
		volumeBar,
		audio,
		audioPlayerState,
	);
}

export function handleVolumeMove(
	event: PointerEvent,
	dragState: VolumeDragState,
	volumeBar: HTMLElement | null,
	audio: HTMLAudioElement | undefined,
	audioPlayerState: AudioPlayerState,
) {
	if (!dragState.isPointerDown) {
		return;
	}
	event.preventDefault();

	dragState.isVolumeDragging = true;
	if (dragState.rafId) {
		return;
	}

	dragState.rafId = requestAnimationFrame(() => {
		updateVolumeLogic(
			event.clientX,
			dragState,
			volumeBar,
			audio,
			audioPlayerState,
		);
		dragState.rafId = null;
	});
}

export function stopVolumeDrag(
	event: PointerEvent,
	dragState: VolumeDragState,
	volumeBar: HTMLElement | null,
	audioPlayerState: AudioPlayerState,
) {
	if (!dragState.isPointerDown) {
		return;
	}
	dragState.isPointerDown = false;
	dragState.isVolumeDragging = false;
	dragState.volumeBarRect = null;
	if (volumeBar) {
		volumeBar.releasePointerCapture(event.pointerId);
	}

	if (dragState.rafId) {
		cancelAnimationFrame(dragState.rafId);
		dragState.rafId = null;
	}

	saveVolumeToStorage(audioPlayerState);
}

export function handleVolumeKeyDown(
	event: KeyboardEvent,
	onToggleMute: () => void,
) {
	if (event.key === "Enter" || event.key === " ") {
		event.preventDefault();
		if (event.key === "Enter") {
			onToggleMute();
		}
	}
}

