											fontWeight: 700,
											lineHeight: 1.2,
											color: textColor,
											marginLeft: "25px",
											display: "-webkit-box",
											overflow: "hidden",
											textOverflow: "ellipsis",
											lineClamp: 3,
											WebkitLineClamp: 3,
											WebkitBoxOrient: "vertical",
										},
										children: post.data.title,
									},
								},
							],
						},
					},
					description && {
						type: "div",
						props: {
							style: {
								fontSize: "32px",
								lineHeight: 1.5,
								color: subtleTextColor,
								paddingLeft: "35px",
								display: "-webkit-box",
								overflow: "hidden",
								textOverflow: "ellipsis",
								lineClamp: 2,
								WebkitLineClamp: 2,
								WebkitBoxOrient: "vertical",
							},
							children: description,
						},
					},
				].filter(Boolean),
			},
		},
		{
			type: "div",
			props: {
				style: {
					display: "flex",
					justifyContent: "space-between",
					alignItems: "center",
					width: "100%",
				},
				children: [
