(() => {
	// 单例模式：检查是否已经初始化过
	if (window.mermaidInitialized) {
		// 如果已经初始化过，只确保 renderMermaidDiagrams 函数可用
		if (typeof window.renderMermaidDiagrams !== "function") {
			window.renderMermaidDiagrams = renderMermaidDiagrams;
		}
		return;
	}

	window.mermaidInitialized = true;

	// 记录当前主题状态，避免不必要的重新渲染
	let currentTheme = null;
	let isRendering = false; // 防止并发渲染

	function sanitizeSvgString(svgText) {
		if (typeof svgText !== "string" || !svgText.trim()) {
			return "";
		}

		const parser = new DOMParser();
		const doc = parser.parseFromString(svgText, "image/svg+xml");
		const svgRoot = doc.documentElement;

		if (!svgRoot || svgRoot.nodeName.toLowerCase() !== "svg") {
			return "";
		}

		// 移除高风险节点
		doc.querySelectorAll("script, foreignObject").forEach((node) => {
			node.remove();
		});

		// 移除事件处理属性和 javascript: 链接
		doc.querySelectorAll("*").forEach((node) => {
			for (const attr of Array.from(node.attributes)) {
				const name = attr.name.toLowerCase();
				const value = (attr.value || "").trim().toLowerCase();
				if (
					name.startsWith("on") ||
					((name === "href" || name === "xlink:href") &&
						value.startsWith("javascript:"))
				) {
					node.removeAttribute(attr.name);
				}
			}
		});

		return new XMLSerializer().serializeToString(svgRoot);
	}
	let retryCount = 0;
	const MAX_RETRIES = 3;
	const RETRY_DELAY = 1000; // 1秒
	let fullscreenOverlay = null;

	function injectFullscreenStyles() {
		if (document.getElementById("mermaid-fullscreen-style")) {
			return;
		}

		const style = document.createElement("style");
		style.id = "mermaid-fullscreen-style";
		style.textContent = `
		:where(.mermaid[data-mermaid-code]) { position: relative; }
		.mermaid-fullscreen-btn {
			position: absolute;
			top: 10px;
			right: 10px;
			height: 36px;
			width: 36px;
			display: inline-flex;
			align-items: center;
			justify-content: center;
			opacity: 0;
			transition: opacity 0.2s ease;
			z-index: 3;
		}
		.mermaid:hover .mermaid-fullscreen-btn,
		.mermaid:focus-within .mermaid-fullscreen-btn {
			opacity: 1;
		}
		.mermaid-fullscreen-overlay {
			position: fixed;
			inset: 0;
			display: flex;
			align-items: center;
			justify-content: center;
			padding: clamp(12px, 3vw, 28px);
			backdrop-filter: blur(6px);
			z-index: 9999;
			background: var(--mermaid-fs-backdrop, rgba(15, 23, 42, 0.9));
		}
		.mermaid-fullscreen-stage {
			position: relative;
			width: min(1200px, 96vw);
			max-height: 90vh;
			padding: clamp(12px, 2vw, 18px);
			background: var(--mermaid-fs-surface, #0f172a);
			border: 1px solid var(--mermaid-fs-border, rgba(255,255,255,0.08));
			border-radius: 16px;
			box-shadow: 0 20px 80px rgba(0, 0, 0, 0.35);
			overflow: hidden;
		}
		.mermaid-fullscreen-stage svg {
			width: 100%;
			height: auto;
			min-height: 320px;
		}
		.mermaid-fullscreen-close {
			position: absolute;
			top: 10px;
			right: 10px;
			z-index: 4;
		}
		.mermaid-fullscreen-overlay .mermaid-zoom-controls {
			position: absolute;
			left: 12px;
			bottom: 12px;
			display: flex;
			gap: 8px;
		}
		body.mermaid-fullscreen-open { overflow: hidden; }
		`;
		document.head.appendChild(style);
	}

	function getThemePalette() {
		const htmlElement = document.documentElement;
		const isDark = htmlElement.classList.contains("dark");
		const styles = getComputedStyle(htmlElement);
		const primary =
			styles.getPropertyValue("--primary")?.trim() ||
			(isDark ? "#7dd3fc" : "#2563eb");
		const surface =
			styles.getPropertyValue("--card-bg")?.trim() ||
			styles.getPropertyValue("--surface")?.trim() ||
			(isDark ? "#0b1220" : "#ffffff");
		const text =
			styles.getPropertyValue("--text-color")?.trim() ||
			styles.getPropertyValue("--foreground")?.trim() ||
			(isDark ? "#e5e7eb" : "#0f172a");
		const muted =
			styles.getPropertyValue("--muted")?.trim() ||
			styles.getPropertyValue("--muted-foreground")?.trim() ||
			(isDark ? "#1f2937" : "#e5e7eb");
		const backdrop = isDark
			? "rgba(8, 15, 30, 0.9)"
			: "rgba(255, 255, 255, 0.94)";

		return { isDark, primary, surface, text, muted, backdrop };
	}

	function closeFullscreen() {
		if (fullscreenOverlay) {
			fullscreenOverlay.remove();
			fullscreenOverlay = null;
			document.body.classList.remove("mermaid-fullscreen-open");
		}
	}

	function openFullscreen(svgElement) {
		const palette = getThemePalette();
		injectFullscreenStyles();

		closeFullscreen();

		const overlay = document.createElement("div");
		overlay.className = "mermaid-fullscreen-overlay";
		overlay.style.setProperty("--mermaid-fs-backdrop", palette.backdrop);
		overlay.style.setProperty("--mermaid-fs-surface", palette.surface);
		overlay.style.setProperty(
			"--mermaid-fs-border",
			palette.isDark ? "rgba(255,255,255,0.08)" : "rgba(15,23,42,0.08)",
		);

		const closeButton = document.createElement("button");
		closeButton.className =
			"mermaid-fullscreen-close btn-regular rounded-lg h-10 w-10";
		closeButton.title = "关闭全屏";
		closeButton.textContent = "✕";
		closeButton.addEventListener("click", closeFullscreen);

		const stage = document.createElement("div");
		stage.className = "mermaid-fullscreen-stage";

		const clonedSvg = svgElement.cloneNode(true);
		stage.appendChild(clonedSvg);
		overlay.appendChild(stage);
		overlay.appendChild(closeButton);

		overlay.addEventListener("click", (ev) => {
			if (ev.target === overlay) {
				closeFullscreen();
			}
		});

		const escHandler = (ev) => {
			if (ev.key === "Escape") {
				closeFullscreen();
			}
		};
		window.addEventListener("keydown", escHandler, { once: true });

		document.body.appendChild(overlay);
		document.body.classList.add("mermaid-fullscreen-open");
		fullscreenOverlay = overlay;

		// 为全屏内的图表添加缩放控制
		attachZoomControls(stage, clonedSvg);
	}

	function ensureFullscreenButton(element) {
		if (element.querySelector(".mermaid-fullscreen-btn")) {
			return;
		}
		const btn = document.createElement("button");
		btn.type = "button";
		btn.className = "mermaid-fullscreen-btn btn-regular rounded-lg h-9 w-9";
		btn.title = "全屏查看";
		btn.setAttribute("aria-label", "全屏查看 Mermaid 图表");
		btn.innerHTML = "⛶";
		btn.addEventListener("click", (ev) => {
			ev.stopPropagation();
			const svg = element.querySelector("svg");
			if (!svg) {return;}
			openFullscreen(svg);
		});
		element.appendChild(btn);
	}

	// 检查主题是否真的发生了变化
	function hasThemeChanged() {
		const isDark = document.documentElement.classList.contains("dark");
		const newTheme = isDark ? "dark" : "default";

		if (currentTheme !== newTheme) {
			currentTheme = newTheme;
			return true;
		}
		return false;
	}

	// 等待 Mermaid 库加载完成
	function waitForMermaid(timeout = 10000) {
		return new Promise((resolve, reject) => {
			const startTime = Date.now();

			function check() {
				if (
					window.mermaid &&
					typeof window.mermaid.initialize === "function"
				) {
					resolve(window.mermaid);
				} else if (Date.now() - startTime > timeout) {
					reject(
						new Error(
							"Mermaid library failed to load within timeout",
						),
					);
				} else {
					setTimeout(check, 100);
				}
			}

			check();
		});
	}

	// 存储 MutationObserver 实例
	let themeObserver = null;

	// 清理 MutationObserver
	function cleanupMutationObserver() {
		if (themeObserver) {
			themeObserver.disconnect();
			themeObserver = null;
		}
	}

	// 设置 MutationObserver 监听 html 元素的 class 属性变化
	function setupMutationObserver() {
		cleanupMutationObserver();

		themeObserver = new MutationObserver((mutations) => {
			mutations.forEach((mutation) => {
				if (
					mutation.type === "attributes" &&
					mutation.attributeName === "class"
				) {
					// 检查是否是 dark 类的变化
					const target = mutation.target;
					const wasDark = mutation.oldValue
						? mutation.oldValue.includes("dark")
						: false;
					const isDark = target.classList.contains("dark");

					if (wasDark !== isDark) {
						if (hasThemeChanged()) {
							// 延迟渲染，避免主题切换时的闪烁
							setTimeout(() => renderMermaidDiagrams(), 150);
						}
					}
				}
			});
		});

		// 开始观察 html 元素的 class 属性变化
		themeObserver.observe(document.documentElement, {
			attributes: true,
			attributeFilter: ["class"],
			attributeOldValue: true,
		});
	}

	// 缩放平移
	function attachZoomControls(element, svgElement) {
		if (element.__zoomAttached) {
			return;
		}
		element.__zoomAttached = true;

		const wrapper = document.createElement("div");
		wrapper.className = "mermaid-zoom-wrapper";

		const svgParent = svgElement.parentNode;
		wrapper.appendChild(svgElement);
		svgParent.appendChild(wrapper);

		let scale = 1;
		let tx = 0;
		let ty = 0;
		const MIN_SCALE = 0.2;
		const MAX_SCALE = 6;

		function applyTransform() {
			wrapper.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
		}
		const controls = document.createElement("div");
		controls.className = "mermaid-zoom-controls";
		controls.innerHTML = `
			<button class="btn-regular rounded-lg h-10 w-10 active:scale-90" data-action="zoom-in" title="Zoom in">+</button>
			<button class="btn-regular rounded-lg h-10 w-10 active:scale-90" data-action="zoom-out" title="Zoom out">−</button>
			<button class="btn-regular rounded-lg h-10 w-10 active:scale-90" data-action="reset" title="Reset">⤾</button>
		`;
		element.appendChild(controls);

		controls.addEventListener("click", (ev) => {
			const action =
				ev.target.getAttribute && ev.target.getAttribute("data-action");
			if (!action) {
				return;
			}

			switch (action) {
				case "zoom-in":
					scale = Math.min(MAX_SCALE, +(scale * 1.2).toFixed(3));
					applyTransform();
					break;
				case "zoom-out":
					scale = Math.max(MIN_SCALE, +(scale / 1.2).toFixed(3));
					applyTransform();
					break;
				case "reset":
					scale = 1;
					tx = 0;
					ty = 0;
					applyTransform();
					break;
			}
		});

		let isPanning = false;
		let startX = 0;
		let startY = 0;
		let startTx = 0;
		let startTy = 0;

		wrapper.style.touchAction = "none";

		wrapper.addEventListener("pointerdown", (ev) => {
			if (ev.button !== 0) {
				return;
			} // 仅左键
			isPanning = true;
			wrapper.setPointerCapture(ev.pointerId);
			startX = ev.clientX;
			startY = ev.clientY;
			startTx = tx;
			startTy = ty;
		});

		wrapper.addEventListener("pointermove", (ev) => {
			if (!isPanning) {
				return;
			}
			const dx = ev.clientX - startX;
			const dy = ev.clientY - startY;
			tx = startTx + dx / scale; // 根据当前缩放调整灵敏度
			ty = startTy + dy / scale;
			applyTransform();
		});

		wrapper.addEventListener("pointerup", (ev) => {
			isPanning = false;
			try {
				wrapper.releasePointerCapture(ev.pointerId);
			} catch (e) {}
		});

		wrapper.addEventListener("pointercancel", () => {
			isPanning = false;
		});

		// 鼠标滚轮缩放
		element.addEventListener(
			"wheel",
			(ev) => {
				ev.preventDefault();
				const delta = -ev.deltaY;
				const zoomFactor = delta > 0 ? 1.12 : 1 / 1.12;
				const prevScale = scale;
				scale = Math.min(
					MAX_SCALE,
					Math.max(MIN_SCALE, +(scale * zoomFactor).toFixed(3)),
				);

				const rect = wrapper.getBoundingClientRect();
				const cx = ev.clientX - rect.left;
				const cy = ev.clientY - rect.top;

				const worldX = cx / prevScale - tx;
				const worldY = cy / prevScale - ty;

				tx = cx / scale - worldX;
				ty = cy / scale - worldY;

				applyTransform();
			},
			{ passive: false },
		);

		// 双击重置
		wrapper.addEventListener("dblclick", () => {
			scale = 1;
			tx = 0;
			ty = 0;
			applyTransform();
		});
		applyTransform();
		let resizeTimer = null;
		window.addEventListener("resize", () => {
			clearTimeout(resizeTimer);
			resizeTimer = setTimeout(() => {
				applyTransform();
			}, 200);
		});
	}

	// 设置其他事件监听器
	function setupEventListeners() {
		// 监听页面切换
		document.addEventListener("astro:page-load", () => {
			// 重新初始化主题状态
			currentTheme = null;
			retryCount = 0; // 重置重试计数
			if (hasThemeChanged()) {
				setTimeout(() => renderMermaidDiagrams(), 100);
			}
		});

		// 监听页面可见性变化，页面重新可见时重新渲染
		document.addEventListener("visibilitychange", () => {
			if (!document.hidden) {
				setTimeout(() => renderMermaidDiagrams(), 200);
			}
		});

		// 页面切换前清理
		document.addEventListener("astro:before-swap", cleanupMutationObserver);

		// 页面切换前清理全屏状态
		document.addEventListener("astro:before-swap", closeFullscreen);

		// Swup 页面切换时重新设置 Observer
		document.addEventListener("astro:after-swap", () => {
			if (themeObserver === null) {
				setupMutationObserver();
			}
		});
	}

	async function initializeMermaid() {
		try {
			await waitForMermaid();

			// 初始化 Mermaid 配置
			window.mermaid.initialize({
				startOnLoad: false,
				theme: "default",
				themeVariables: {
					fontFamily: "inherit",
					fontSize: "16px",
				},
				securityLevel: "loose",
				// 添加错误处理配置
				errorLevel: "warn",
				logLevel: "error",
			});

			// 渲染所有 Mermaid 图表
			await renderMermaidDiagrams();
		} catch (error) {
			console.error("Failed to initialize Mermaid:", error);
			// 如果初始化失败，尝试重新加载
			if (retryCount < MAX_RETRIES) {
				retryCount++;
				setTimeout(() => initializeMermaid(), RETRY_DELAY * retryCount);
			}
		}
	}

	async function renderMermaidDiagrams() {
		// 防止并发渲染
		if (isRendering) {
			return;
		}

		// 检查 Mermaid 是否可用
		if (!window.mermaid || typeof window.mermaid.render !== "function") {
			console.warn("Mermaid not available, skipping render");
			return;
		}

		isRendering = true;
		window.dispatchEvent(new CustomEvent("mermaid:render:start"));

		try {
			const mermaidElements = Array.from(
				document.querySelectorAll(".mermaid[data-mermaid-code]"),
			);

			if (mermaidElements.length === 0) {
				isRendering = false;
				window.dispatchEvent(
					new CustomEvent("mermaid:render:done", {
						detail: { count: 0 },
					}),
				);
				return;
			}

			// 延迟检测主题，确保 DOM 已经更新
			await new Promise((resolve) => setTimeout(resolve, 100));

			const htmlElement = document.documentElement;
			const isDark = htmlElement.classList.contains("dark");
			const theme = isDark ? "dark" : "default";

			// 更新 Mermaid 主题（只需要更新一次）
			window.mermaid.initialize({
				startOnLoad: false,
				theme: theme,
				themeVariables: {
					fontFamily: "inherit",
					fontSize: "16px",
					// 强制应用主题变量
					primaryColor: isDark ? "#ffffff" : "#000000",
					primaryTextColor: isDark ? "#ffffff" : "#000000",
					primaryBorderColor: isDark ? "#ffffff" : "#000000",
					lineColor: isDark ? "#ffffff" : "#000000",
					secondaryColor: isDark ? "#333333" : "#f0f0f0",
					tertiaryColor: isDark ? "#555555" : "#e0e0e0",
				},
				securityLevel: "loose",
				errorLevel: "warn",
				logLevel: "error",
			});

			// 分批渲染，避免一次性阻塞主线程
			const BATCH_SIZE = 3;
			let index = 0;

			async function renderBatch() {
				const batch = mermaidElements.slice(index, index + BATCH_SIZE);
				if (batch.length === 0) {
					return;
				}

				await Promise.all(
					batch.map(async (element, localIndex) => {
						const globalIndex = index + localIndex;
						let attempts = 0;
						const maxAttempts = 3;

						while (attempts < maxAttempts) {
							try {
								const code =
									element.getAttribute("data-mermaid-code");

								if (!code) {
									break;
								}

								// 显示加载状态
								element.innerHTML =
									'<div class="mermaid-loading">Rendering diagram...</div>';

								// 渲染图表
								const { svg } = await window.mermaid.render(
									`mermaid-${Date.now()}-${globalIndex}-${attempts}`,
									code,
								);

								const safeSvg = sanitizeSvgString(svg);
								if (!safeSvg) {
									throw new Error("Invalid or unsafe SVG output");
								}
								const parser = new DOMParser();
								const doc = parser.parseFromString(
									safeSvg,
									"image/svg+xml",
								);
								const svgElement = doc.documentElement;

								element.innerHTML = "";
								element.__zoomAttached = false;
								element.appendChild(svgElement);

								// 添加响应式支持
								const insertedSvg =
									element.querySelector("svg");
								if (insertedSvg) {
									insertedSvg.setAttribute("width", "100%");
									insertedSvg.removeAttribute("height");
									insertedSvg.style.maxWidth = "100%";
									insertedSvg.style.height = "auto";
									//Todo 需要根据实际情况
									insertedSvg.style.minHeight = "300px";

									// 强制应用样式
									if (isDark) {
										svgElement.style.filter =
											"brightness(0.9) contrast(1.1)";
									} else {
										svgElement.style.filter = "none";
									}
									attachZoomControls(element, insertedSvg);
									ensureFullscreenButton(element);
								}

								// 渲染成功，跳出重试循环
								break;
							} catch (error) {
								attempts++;
								console.warn(
									`Mermaid rendering attempt ${attempts} failed for element ${globalIndex}:`,
									error,
								);

								if (attempts >= maxAttempts) {
									console.error(
										`Failed to render Mermaid diagram after ${maxAttempts} attempts:`,
										error,
									);
									element.innerHTML = "";
									const errorWrapper = document.createElement("div");
									errorWrapper.className = "mermaid-error";

									const errorText = document.createElement("p");
									errorText.textContent = `Failed to render diagram after ${maxAttempts} attempts.`;

									const retryButton = document.createElement("button");
									retryButton.textContent = "Retry Page";
									retryButton.style.marginTop = "8px";
									retryButton.style.padding = "4px 8px";
									retryButton.style.background = "var(--primary)";
									retryButton.style.color = "white";
									retryButton.style.border = "none";
									retryButton.style.borderRadius = "4px";
									retryButton.style.cursor = "pointer";
									retryButton.addEventListener("click", () => location.reload());

									errorWrapper.appendChild(errorText);
									errorWrapper.appendChild(retryButton);
									element.appendChild(errorWrapper);
								} else {
									// 等待一段时间后重试
									await new Promise((resolve) =>
										setTimeout(resolve, 500 * attempts),
									);
								}
							}
						}
					}),
				);

				index += BATCH_SIZE;

				if (index < mermaidElements.length) {
					// 在空闲时间继续渲染下一批，避免长时间阻塞主线程
					await new Promise((resolve) => {
						if ("requestIdleCallback" in window) {
							window.requestIdleCallback(() => resolve());
						} else {
							setTimeout(resolve, 50);
						}
					});
					return renderBatch();
				}
			}

			await renderBatch();
			retryCount = 0; // 重置重试计数
			window.dispatchEvent(
				new CustomEvent("mermaid:render:done", {
					detail: { count: mermaidElements.length },
				}),
			);
		} catch (error) {
			console.error("Error in renderMermaidDiagrams:", error);
			window.dispatchEvent(new CustomEvent("mermaid:render:done"));

			// 如果渲染失败，尝试重新渲染
			if (retryCount < MAX_RETRIES) {
				retryCount++;
				setTimeout(
					() => renderMermaidDiagrams(),
					RETRY_DELAY * retryCount,
				);
			}
		} finally {
			isRendering = false;
		}
	}

	// 初始化主题状态
	function initializeThemeState() {
		const isDark = document.documentElement.classList.contains("dark");
		currentTheme = isDark ? "dark" : "default";
	}

	// 加载 Mermaid 库
	async function loadMermaid() {
		if (typeof window.mermaid !== "undefined") {
			return Promise.resolve();
		}

		return new Promise((resolve, reject) => {
			const script = document.createElement("script");
			script.src =
				"https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js";

			script.onload = () => {
				console.log("Mermaid library loaded successfully");
				resolve();
			};

			script.onerror = (error) => {
				console.error("Failed to load Mermaid library:", error);
				// 尝试备用 CDN
				const fallbackScript = document.createElement("script");
				fallbackScript.src =
					"https://unpkg.com/mermaid@11/dist/mermaid.min.js";

				fallbackScript.onload = () => {
					console.log("Mermaid library loaded from fallback CDN");
					resolve();
				};

				fallbackScript.onerror = () => {
					reject(
						new Error(
							"Failed to load Mermaid from both primary and fallback CDNs",
						),
					);
				};

				document.head.appendChild(fallbackScript);
			};

			document.head.appendChild(script);
		});
	}

	// 主初始化函数
	async function initialize() {
		try {
			// 设置监听器
			setupMutationObserver();
			setupEventListeners();

			// 初始化主题状态
			initializeThemeState();

			// 加载并初始化 Mermaid
			await loadMermaid();
			await initializeMermaid();

			// 将 renderMermaidDiagrams 暴露到全局作用域，以便在解密后调用
			window.renderMermaidDiagrams = renderMermaidDiagrams;
		} catch (error) {
			console.error("Failed to initialize Mermaid system:", error);
		}
	}

	// 启动初始化
	if (document.readyState === "loading") {
		document.addEventListener("DOMContentLoaded", initialize);
	} else {
		initialize();
	}
})();

class CodeBlockCollapser {
	constructor() {
		this.processedBlocks = new WeakSet();
		this.observer = null;
		this.isThemeChanging = false;
		this.debug = false; // 设置为 true 启用调试日志
		this.init();
	}

	log(...args) {
		if (this.debug) {
			console.log("[CodeBlockCollapser]", ...args);
		}
	}

	init() {
		this.log("Initializing...");
		if (document.readyState === "loading") {
			document.addEventListener("DOMContentLoaded", () => {
				this.log("DOMContentLoaded - setting up code blocks");
				this.setupCodeBlocks();
			});
		} else {
			this.log("Document already loaded - setting up code blocks");
			this.setupCodeBlocks();
		}
		this.observePageChanges();
		this.setupThemeChangeListener();
		this.setupThemeOptimizerSync();
	}

	setupThemeOptimizerSync() {
		// 与主题优化器同步，确保代码块的隐藏/显示行为一致
		this.syncWithThemeOptimizer();

		// 监听主题优化器初始化完成事件
		document.addEventListener("themeOptimizerReady", () => {
			this.log("Theme optimizer ready, syncing code block behavior");
			this.syncWithThemeOptimizer();
		});

		// 监听页面切换事件，确保同步
		document.addEventListener("swup:pageView", () => {
			// 延迟同步，确保主题优化器已经处理完代码块
			setTimeout(() => {
				this.syncWithThemeOptimizer();
			}, 150);
		});
	}

	syncWithThemeOptimizer() {
		// 检查主题优化器是否存在
		if (window.themeOptimizer) {
			// 获取当前主题优化器的设置
			const shouldHideDuringTransition =
				window.themeOptimizer.hideCodeBlocksDuringTransition;

			// 应用相同的设置到代码块
			const codeBlocks = document.querySelectorAll(".expressive-code");
			codeBlocks.forEach((block) => {
				if (shouldHideDuringTransition) {
					block.classList.add("hide-during-transition");
				} else {
					block.classList.remove("hide-during-transition");
				}
			});

			this.log(
				`Synced with theme optimizer: hide code blocks during transition = ${shouldHideDuringTransition}`,
			);
		} else {
			// 如果主题优化器不存在，应用默认行为
			const codeBlocks = document.querySelectorAll(".expressive-code");
			codeBlocks.forEach((block) => {
				block.classList.add("hide-during-transition");
			});

			this.log("Theme optimizer not available, applied default behavior");
		}
	}

	setupThemeChangeListener() {
		// 监听主题切换，在切换期间暂停 observer 和优化性能
		const themeObserver = new MutationObserver((mutations) => {
			for (const mutation of mutations) {
				if (
					mutation.type === "attributes" &&
					(mutation.attributeName === "class" ||
						mutation.attributeName === "data-theme")
				) {
					const isTransitioning =
						document.documentElement.classList.contains(
							"is-theme-transitioning",
						);

					if (isTransitioning && !this.isThemeChanging) {
						this.isThemeChanging = true;

						// 断开 observer 以避免在主题切换时进行不必要的检查
						if (this.observer) {
							this.observer.disconnect();
						}

						// 性能优化：临时禁用代码块的动画和过渡
						document
							.querySelectorAll(".expressive-code")
							.forEach((block) => {
								block.style.transition = "none";
							});
					} else if (!isTransitioning && this.isThemeChanging) {
						this.isThemeChanging = false;

						// 等待主题切换完全结束后再恢复
						requestAnimationFrame(() => {
							// 恢复代码块的过渡效果
							document
								.querySelectorAll(".expressive-code")
								.forEach((block) => {
									block.style.transition = "";
								});

							// 重新连接 observer
							setTimeout(() => {
								this.observePageChanges();
							}, 50);
						});
					}
					break;
				}
			}
		});

		themeObserver.observe(document.documentElement, {
			attributes: true,
			attributeFilter: ["class", "data-theme"],
		});
	}

	setupCodeBlocks() {
		requestAnimationFrame(() => {
			const codeBlocks = document.querySelectorAll(".expressive-code");
			this.log(`Found ${codeBlocks.length} code blocks to process`);

			codeBlocks.forEach((codeBlock, index) => {
				if (!this.processedBlocks.has(codeBlock)) {
					this.log(`Enhancing code block ${index + 1}`);
					this.enhanceCodeBlock(codeBlock);
					this.processedBlocks.add(codeBlock);
				} else {
					this.log(`Code block ${index + 1} already processed`);
				}
			});
		});
	}

	enhanceCodeBlock(codeBlock) {
		const frame = codeBlock.querySelector(".frame");
		if (!frame) {
			this.log("No frame found in code block, skipping");
			return;
		}

		if (frame.classList.contains("has-title")) {
			this.log("Code block has title, skipping collapse feature");
			return;
		}

		this.log("Adding collapse feature to code block");
		codeBlock.classList.add("collapsible", "expanded");

		const toggleBtn = this.createToggleButton();
		frame.appendChild(toggleBtn);

		this.bindToggleEvents(codeBlock, toggleBtn);
	}

	createToggleButton() {
		const button = document.createElement("button");
		button.className = "collapse-toggle-btn";
		button.type = "button";
		button.setAttribute("aria-label", "折叠/展开代码块");

		button.innerHTML = `
      <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
        <g fill="none">
          <path d="M24 0v24H0V0zM12.593 23.258l-.011.002l-.071.035l-.02.004l-.014-.004l-.071-.035q-.016-.005-.024.005l-.004.01l-.017.428l.005.02l.01.013l.104.074l.015.004l.012-.004l.104-.074l.012-.016l.004-.017l-.017-.427q-.004-.016-.017-.018m.265-.113l-.013.002l-.185.093l-.01.01l-.003.011l.018.43l.005.012l.008.007l.201.093q.019.005.029-.008l.004-.014l-.034-.614q-.005-.019-.02-.022m-.715.002a.02.02 0 0 0-.027.006l-.006.014l-.034.614q.001.018.017.024l.015-.002l.201-.093l.01-.008l.004-.011l.017-.43l-.003-.012l-.01-.01z"></path>
          <path fill="currentColor" d="m12 16.172l-4.95-4.95a1 1 0 1 0-1.414 1.414l5.657 5.657a1 1 0 0 0 1.414 0l5.657-5.657a1 1 0 0 0-1.414-1.414z"></path>
        </g>
      </svg>
    `;

		return button;
	}

	bindToggleEvents(codeBlock, button) {
		button.addEventListener("click", (e) => {
			e.preventDefault();
			e.stopPropagation();
			this.toggleCollapse(codeBlock);
		});

		button.addEventListener("keydown", (e) => {
			if (e.key === "Enter" || e.key === " ") {
				e.preventDefault();
				this.toggleCollapse(codeBlock);
			}
		});
	}

	toggleCollapse(codeBlock) {
		const isCollapsed = codeBlock.classList.contains("collapsed");

		requestAnimationFrame(() => {
			if (isCollapsed) {
				codeBlock.classList.remove("collapsed");
				codeBlock.classList.add("expanded");
			} else {
				codeBlock.classList.remove("expanded");
				codeBlock.classList.add("collapsed");
			}
		});

		const event = new CustomEvent("codeBlockToggle", {
			detail: { collapsed: !isCollapsed, element: codeBlock },
		});
		document.dispatchEvent(event);
	}

	observePageChanges() {
		// 如果正在主题切换，不要重新连接
		if (this.isThemeChanging) {
			return;
		}

		// 断开现有的 observer
		if (this.observer) {
			this.observer.disconnect();
		}

		let debounceTimer = null;

		this.observer = new MutationObserver((mutations) => {
			// 如果正在主题切换，忽略所有变化
			if (this.isThemeChanging) {
				return;
			}

			let shouldReinit = false;

			// 外层循环：遍历所有变动
			for (const mutation of mutations) {
				if (
					mutation.type === "childList" &&
					mutation.addedNodes.length > 0
				) {
					// 内层循环：遍历新增节点
					for (const node of mutation.addedNodes) {
						// 只检查元素节点 (nodeType 1)
						if (node.nodeType === Node.ELEMENT_NODE) {
							if (
								node.classList.contains("expressive-code") ||
								(node.getElementsByClassName &&
									node.getElementsByClassName(
										"expressive-code",
									).length > 0)
							) {
								shouldReinit = true;
								break;
							}
						}
					}
				}
				if (shouldReinit) {
					break;
				}
			}

			if (shouldReinit) {
				clearTimeout(debounceTimer);
				debounceTimer = setTimeout(() => this.setupCodeBlocks(), 30);
			}
		});

		this.observer.observe(document.body, {
			childList: true,
			subtree: true,
		});
	}

	destroy() {
		if (this.observer) {
			this.observer.disconnect();
			this.observer = null;
		}
		this.processedBlocks = new WeakSet();
	}

	// 公共API方法
	collapseAll() {
		const allBlocks = document.querySelectorAll(
			".expressive-code.expanded",
		);
		allBlocks.forEach((block) => {
			this.toggleCollapse(block);
		});
	}

	expandAll() {
		const allBlocks = document.querySelectorAll(
			".expressive-code.collapsed",
		);
		allBlocks.forEach((block) => {
			this.toggleCollapse(block);
		});
	}
}

const codeBlockCollapser = new CodeBlockCollapser();

window.CodeBlockCollapser = CodeBlockCollapser;
window.codeBlockCollapser = codeBlockCollapser;

// 设置 Swup 钩子的函数
function setupSwupHooks() {
	if (window.swup) {
		codeBlockCollapser.log("Setting up Swup hooks");

		// 监听 page:view 事件
		window.swup.hooks.on("page:view", () => {
			codeBlockCollapser.log(
				"Swup page:view event - reinitializing code blocks",
			);
			// 页面切换后重置 processedBlocks，确保新页面的代码块被处理
			codeBlockCollapser.processedBlocks = new WeakSet();
			setTimeout(() => {
				codeBlockCollapser.setupCodeBlocks();
			}, 100);
		});

		// 监听 content:replace 事件（更早触发）
		window.swup.hooks.on("content:replace", () => {
			codeBlockCollapser.log(
				"Swup content:replace event - preparing for reinitialization",
			);
			// 内容替换时也重置，确保不会因为缓存而跳过处理
			codeBlockCollapser.processedBlocks = new WeakSet();
			setTimeout(() => {
				codeBlockCollapser.setupCodeBlocks();
			}, 50);
		});

		return true;
	}
	return false;
}

// 尝试立即设置 Swup 钩子
if (!setupSwupHooks()) {
	// 如果 Swup 尚未初始化，等待它加载
	codeBlockCollapser.log("Swup not ready, waiting for initialization");

	// 监听 swup:enable 事件
	document.addEventListener("swup:enable", () => {
		codeBlockCollapser.log("Swup enabled, setting up hooks");
		setupSwupHooks();
	});

	// 额外的延迟重试机制，确保捕获到 Swup
	const retryInterval = setInterval(() => {
		if (setupSwupHooks()) {
			codeBlockCollapser.log("Swup hooks set up successfully via retry");
			clearInterval(retryInterval);
		}
	}, 100);

	// 最多重试 20 次（2 秒）
	setTimeout(() => {
		clearInterval(retryInterval);
	}, 2000);
}

/**
 * Swup 钩子模块
 * 处理页面过渡过程中的各种钩子事件
 */

import { pathsEqual, url } from "../../utils/url-utils";
import type { FancyboxHandler } from "../handlers/fancybox-handler";
import type { ScrollHandler } from "../handlers/scroll-handler";
import {
	ANIMATION_CONFIG,
	BANNER_HEIGHT,
	SWUP_SELECTORS,
	THEME_CONFIG,
} from "./swup-config";

// 钩子处理器接口
export interface SwupHookHandlers {
	fancyboxHandler?: FancyboxHandler;
	scrollHandler?: ScrollHandler;
	showBanner?: () => void;
	initFancybox?: () => void;
	cleanupFancybox?: () => void;
	initCustomScrollbar?: () => void;
	checkKatex?: () => void;
}

// 访问对象类型
interface VisitObject {
	to: {
		url: string;
	};
}

/**
 * Swup 钩子管理器
 * 负责注册和管理所有 Swup 页面过渡钩子
 */
export class SwupHooksManager {
	private bannerEnabled: boolean;
	private handlers: SwupHookHandlers;

	private cachedElements: Map<string, Element | null> = new Map();

	constructor(bannerEnabled: boolean, handlers: SwupHookHandlers = {}) {
		this.bannerEnabled = bannerEnabled;
		this.handlers = handlers;
	}

	private getCachedElement(selector: string): Element | null {
		if (!this.cachedElements.has(selector)) {
			const id = selector.startsWith("#") ? selector.slice(1) : selector;
			if (selector.startsWith("#")) {
				this.cachedElements.set(selector, document.getElementById(id));
			} else {
				this.cachedElements.set(
					selector,
					document.querySelector(selector),
				);
			}
		}
		return this.cachedElements.get(selector) ?? null;
	}

	private clearCache(): void {
		this.cachedElements.clear();
	}

	/**
	 * 注册所有 Swup 钩子
	 */
	registerHooks(): void {
		if (!window.swup) {
			return;
		}
		this.registerLinkClickHook();
		this.registerContentReplaceHook();
		this.registerVisitStartHook();
		this.registerPageViewHook();
		this.registerVisitEndHook();
	}

	/**
	 * link:click 钩子
	 * 处理链接点击时的初始状态
	 */
	private registerLinkClickHook(): void {
		window.swup!.hooks.on("link:click", () => {
			// 移除首次页面加载的延迟
			document.documentElement.style.setProperty(
				"--content-delay",
				"0ms",
			);

			// 处理 navbar 隐藏
			if (this.bannerEnabled) {
				this.handleNavbarHideOnLinkClick();
			}
		});
	}

	/**
	 * content:replace 钩子
	 * 处理内容替换后的初始化
	 */
	private registerContentReplaceHook(): void {
		window.swup!.hooks.on("content:replace", () => {
			this.clearCache();

			// 初始化新页面的图片、公式、滚动条和 TOC
			this.handlers.initFancybox?.();
			this.handlers.checkKatex?.();
			this.handlers.initCustomScrollbar?.();

			// 处理 TOC 重新初始化
			this.handleTOCReinit();

			// 重新初始化 semifull 模式滚动检测
			this.reinitSemifullScrollDetection();
		});
	}

	/**
	 * visit:start 钩子
	 * 处理页面访问开始时的状态
	 */
	private registerVisitStartHook(): void {
		window.swup!.hooks.on("visit:start", (visit: VisitObject) => {
			// 清理上一页的 Fancybox
			this.handlers.cleanupFancybox?.();

			// 处理页面状态
			const isHomePage = pathsEqual(visit.to.url, url("/"));
			this.handleBodyClass(isHomePage);
			this.handleBannerTextVisibility(isHomePage);
			this.handleNavbarState(isHomePage);
			this.handleMobileBannerVisibility(isHomePage);

			// 扩展页面高度防止滚动动画跳跃
			this.extendPageHeight(false);

			// 隐藏 TOC
			this.hideTOC();
		});
	}

	/**
	 * page:view 钩子
	 * 处理页面视图显示
	 */
	private registerPageViewHook(): void {
		window.swup!.hooks.on("page:view", () => {
			// 扩展页面高度
			this.extendPageHeight(false);

			// 滚动到页面顶部
			window.scrollTo({
				top: 0,
				behavior: "instant",
			});

			// 同步主题状态
			this.syncThemeState();

			// 触发页面加载完成事件
			this.dispatchPageLoadedEvent();
		});
	}

	/**
	 * visit:end 钩子
	 * 处理页面访问结束时的清理
	 */
	private registerVisitEndHook(): void {
		window.swup!.hooks.on("visit:end", (_visit: VisitObject) => {
			setTimeout(() => {
				// 隐藏高度扩展元素
				this.extendPageHeight(true);

				// 显示 TOC
				this.showTOC();
			}, ANIMATION_CONFIG.heightExtendDelay);
		});
	}

	// ==================== 私有辅助方法 ====================

	/**
	 * 处理链接点击时的 navbar 隐藏
	 */
	private handleNavbarHideOnLinkClick(): void {
		const navbar = this.getCachedElement(SWUP_SELECTORS.navbarWrapper);
		if (navbar && document.body.classList.contains("lg:is-home")) {
			const threshold = window.innerHeight * (BANNER_HEIGHT / 100) - 88;
			if (document.documentElement.scrollTop >= threshold) {
				navbar.classList.add("navbar-hidden");
			}
		}
	}

	/**
	 * 处理 TOC 重新初始化
	 */
	private handleTOCReinit(): void {
		const tocWrapper = this.getCachedElement(SWUP_SELECTORS.tocWrapper);
		const isArticlePage = tocWrapper !== null;

		if (isArticlePage) {
			const tocElement = this.getCachedElement(
				SWUP_SELECTORS.tableOfContents,
			);
			const hasDesktopTOC =
				tocElement && typeof (tocElement as any).init === "function";
			const hasMobileTOC =
				typeof (window as any).mobileTOCInit === "function";

			if (hasDesktopTOC || hasMobileTOC) {
				setTimeout(() => {
					if (hasDesktopTOC) {
						(tocElement as any).init();
					}
					if (hasMobileTOC) {
						(window as any).mobileTOCInit();
					}
				}, ANIMATION_CONFIG.tocReadyDelay);
			}
		}
	}

	/**
	 * 重新初始化 semifull 模式滚动检测
	 */
	private reinitSemifullScrollDetection(): void {
		const navbar = this.getCachedElement(SWUP_SELECTORS.navbar);
		if (navbar) {
			const transparentMode = navbar.getAttribute(
				"data-transparent-mode",
			);
			if (transparentMode === "semifull") {
				if (
					typeof (window as any).initSemifullScrollDetection ===
					"function"
				) {
					(window as any).initSemifullScrollDetection();
				}
			}
		}
	}

	/**
	 * 处理 body class
	 */
	private handleBodyClass(isHomePage: boolean): void {
		const bodyElement = this.getCachedElement("body");
		if (bodyElement) {
			if (isHomePage) {
				bodyElement.classList.add("lg:is-home");
			} else {
				bodyElement.classList.remove("lg:is-home");
			}
		}
	}

	/**
	 * 处理 Banner 文字可见性
	 */
	private handleBannerTextVisibility(isHomePage: boolean): void {
		const bannerTextOverlay = this.getCachedElement(
			SWUP_SELECTORS.bannerTextOverlay,
		);
		if (bannerTextOverlay) {
			if (isHomePage) {
				bannerTextOverlay.classList.remove("hidden");
			} else {
				bannerTextOverlay.classList.add("hidden");
			}
		}
	}

	/**
	 * 处理 Navbar 状态
	 */
	private handleNavbarState(isHomePage: boolean): void {
		const navbar = this.getCachedElement(SWUP_SELECTORS.navbar);
		if (navbar) {
			navbar.setAttribute("data-is-home", isHomePage.toString());

			// 重新初始化 semifull 模式滚动检测
			const transparentMode = navbar.getAttribute(
				"data-transparent-mode",
			);
			if (transparentMode === "semifull") {
				if (
					typeof (window as any).initSemifullScrollDetection ===
					"function"
				) {
					(window as any).initSemifullScrollDetection();
				}
			}
		}
	}

	/**
	 * 处理移动端 Banner 可见性
	 */
	private handleMobileBannerVisibility(isHomePage: boolean): void {
		const bannerWrapper = this.getCachedElement(
			SWUP_SELECTORS.bannerWrapper,
		);
		const mainContentWrapper = this.getCachedElement(
			".absolute.w-full.z-30",
		);

		if (bannerWrapper && mainContentWrapper) {
			if (isHomePage) {
				// 首页：延迟移除隐藏类
				setTimeout(() => {
					bannerWrapper.classList.remove("mobile-hide-banner");
				}, ANIMATION_CONFIG.mobileBannerDelay);
				setTimeout(() => {
					mainContentWrapper.classList.remove(
						"mobile-main-no-banner",
					);
				}, ANIMATION_CONFIG.mobileContentDelay);
			} else {
				// 非首页：分阶段隐藏
				bannerWrapper.classList.add("mobile-hide-banner");
				setTimeout(() => {
					mainContentWrapper.classList.add("mobile-main-no-banner");
				}, ANIMATION_CONFIG.mobileBannerDelay);
			}
		}
	}

	/**
	 * 扩展/隐藏页面高度
	 */
	private extendPageHeight(hide: boolean): void {
		const heightExtend = this.getCachedElement(
			SWUP_SELECTORS.pageHeightExtend,
		);
		if (!heightExtend) {
			return;
		}

		// 只在 Banner 模式下启用高度扩展
		// fullscreen/none 模式内容往往不足一屏，如果强行扩展高度，
		// 会导致滚动条在页面过渡期间闪现，引发布局左右抖动
		const isBannerMode = document.body.classList.contains("enable-banner");
		if (!isBannerMode) {
			return;
		}

		if (hide) {
			heightExtend.classList.add("hidden");
		} else {
			heightExtend.classList.remove("hidden");
		}
	}

	/**
	 * 隐藏 TOC
	 */
	private hideTOC(): void {
		const toc = this.getCachedElement(SWUP_SELECTORS.tocWrapper);
		if (toc) {
			toc.classList.add("toc-not-ready");
		}
	}

	/**
	 * 显示 TOC
	 */
	private showTOC(): void {
		const toc = this.getCachedElement(SWUP_SELECTORS.tocWrapper);
		if (toc) {
			toc.classList.remove("toc-not-ready");
		}
	}

	/**
	 * 同步主题状态
	 * 解决从首页进入文章页面时代码块渲染问题
	 */
	private syncThemeState(): void {
		const storedTheme =
			localStorage.getItem(THEME_CONFIG.themeStorageKey) ||
			THEME_CONFIG.lightMode;
		const isDark = storedTheme === THEME_CONFIG.darkMode;
		const expectedTheme = isDark
			? THEME_CONFIG.darkExpressiveTheme
			: THEME_CONFIG.lightExpressiveTheme;

		const currentTheme =
			document.documentElement.getAttribute("data-theme");
		const hasDarkClass =
			document.documentElement.classList.contains("dark");

		// 如果主题不匹配，使用批量更新减少重绘
		if (currentTheme !== expectedTheme || hasDarkClass !== isDark) {
			requestAnimationFrame(() => {
				// 同步 data-theme 属性
				if (currentTheme !== expectedTheme) {
					document.documentElement.setAttribute(
						"data-theme",
						expectedTheme,
					);
				}
				// 同步 dark class
				if (hasDarkClass !== isDark) {
					if (isDark) {
						document.documentElement.classList.add("dark");
					} else {
						document.documentElement.classList.remove("dark");
					}
				}
			});
		}
	}

	/**
	 * 触发页面加载完成事件
	 * 用于初始化评论系统
	 */
	private dispatchPageLoadedEvent(): void {
		setTimeout(() => {
			if (
				document.getElementById("tcomment") ||
				document.getElementById("giscus-container")
			) {
				const pageLoadedEvent = new CustomEvent("mizuki:page:loaded", {
					detail: {
						path: window.location.pathname,
						timestamp: Date.now(),
					},
				});
				document.dispatchEvent(pageLoadedEvent);
				console.log(
					"Layout: 触发 mizuki:page:loaded 事件，路径:",
					window.location.pathname,
				);
			}
		}, ANIMATION_CONFIG.commentInitDelay);
	}

	/**
	 * 更新处理器
	 */
	updateHandlers(handlers: Partial<SwupHookHandlers>): void {
		this.handlers = { ...this.handlers, ...handlers };
	}
}

/**
 * 面板处理器
 * 管理面板的点击外部关闭功能
 */

/**
 * 面板配置接口
 */
interface PanelConfig {
	id: string;
	ignoreElements: string[];
}

/**
 * 面板处理器类
 * 负责初始化面板的点击外部关闭功能
 */
export class PanelHandler {
	private panels: PanelConfig[] = [
		{
			id: "display-setting",
			ignoreElements: ["display-setting", "display-settings-switch"],
		},
		{
			id: "nav-menu-panel",
			ignoreElements: ["nav-menu-panel", "nav-menu-switch"],
		},
		{
			id: "search-panel",
			ignoreElements: ["search-panel", "search-bar", "search-switch"],
		},
		{
			id: "mobile-toc-panel",
			ignoreElements: ["mobile-toc-panel", "mobile-toc-switch"],
		},
		{
			id: "wallpaper-mode-panel",
			ignoreElements: ["wallpaper-mode-panel", "wallpaper-mode-switch"],
		},
	];

	private panelManager: any = null;
	private boundClickHandlers = new Map<string, (event: MouseEvent) => void>();

	/**
	 * 初始化面板处理器
	 */
	async init(): Promise<void> {
		try {
			// 动态导入面板管理器
			const module = await import("../../utils/panel-manager.js");
			this.panelManager = module.panelManager;

			// 设置所有面板的点击外部关闭功能
			this.panels.forEach((panel) => {
				this.setupClickOutsideToClose(panel);
			});

			console.log("PanelHandler: 初始化完成");
			return Promise.resolve();
		} catch (error) {
			console.error("PanelHandler: 初始化失败", error);
			return Promise.reject(error);
		}
	}

	/**
	 * 设置点击外部关闭面板
	 */
	private setupClickOutsideToClose(panel: PanelConfig): void {
		const clickHandler = async (event: MouseEvent) => {
			const target = event.target;
			if (!(target instanceof Node)) {
				return;
			}

			// 检查是否点击了忽略的元素
			for (const ignoreId of panel.ignoreElements) {
				const ignoreElement = document.getElementById(ignoreId);
				if (
					ignoreElement === target ||
					ignoreElement?.contains(target)
				) {
					return;
				}
			}

			// 关闭面板
			if (this.panelManager) {
				await this.panelManager.closePanel(panel.id);
			}
		};

		// 存储绑定的处理器以便后续清理
		this.boundClickHandlers.set(panel.id, clickHandler);
		document.addEventListener("click", clickHandler);
	}

	/**
	 * 添加自定义面板配置
	 */
	addPanel(panel: PanelConfig): void {
		this.panels.push(panel);
		if (this.panelManager) {
			this.setupClickOutsideToClose(panel);
		}
	}

	/**
	 * 移除面板配置
	 */
	removePanel(panelId: string): void {
		// 移除事件监听
		const handler = this.boundClickHandlers.get(panelId);
		if (handler) {
			document.removeEventListener("click", handler);
			this.boundClickHandlers.delete(panelId);
		}

		// 从配置中移除
		this.panels = this.panels.filter((p) => p.id !== panelId);
	}

	/**
	 * 销毁处理器
	 */
	destroy(): void {
		// 移除所有事件监听
		this.boundClickHandlers.forEach((handler) => {
			document.removeEventListener("click", handler);
		});
		this.boundClickHandlers.clear();
		this.panelManager = null;
	}

	/**
	 * 获取面板管理器实例
	 */
	getPanelManager(): any {
		return this.panelManager;
	}
}

// 创建全局实例
let globalPanelHandler: PanelHandler | null = null;

/**
 * 获取全局面板处理器实例
 */
export function getPanelHandler(): PanelHandler {
	if (!globalPanelHandler) {
		globalPanelHandler = new PanelHandler();
	}
	return globalPanelHandler;
}

/**
 * 初始化面板处理器（便捷函数）
 */
export async function initPanelHandler(): Promise<void> {
	const handler = getPanelHandler();
	await handler.init();
}

/**
 * Swup 管理器主入口
 * 协调所有子模块，提供统一的页面过渡管理
 */

import { widgetConfigs } from "../config";
import { initLinkPreloading } from "../utils/navigation-utils";
import { SWUP_SELECTORS } from "./core/swup-config";
import { SwupHooksManager } from "./core/swup-hooks";
import { setupSakuraOnDOMReady } from "./effects/sakura-effect";
import {
	destroyTransitionEffect,
	getTransitionEffect,
} from "./effects/transition-effect";
import type { BackToTopHandler } from "./handlers/back-to-top-handler";
import {
	getBackToTopHandler,
	initBackToTopHandler,
} from "./handlers/back-to-top-handler";
import type { FancyboxHandler } from "./handlers/fancybox-handler";
import {
	cleanupFancybox,
	getFancyboxHandler,
	initFancybox,
} from "./handlers/fancybox-handler";
import type { PanelHandler } from "./handlers/panel-handler";
import { getPanelHandler, initPanelHandler } from "./handlers/panel-handler";
import { checkKatex, initCustomScrollbar } from "./handlers/scroll-handler";

/**
 * Swup 管理器类
 * 统一管理页面过渡相关的所有功能
 */
export class SwupManager {
	private hooksManager: SwupHooksManager | null = null;
	private fancyboxHandler: FancyboxHandler;
	private backToTopHandler: BackToTopHandler;
	private panelHandler: PanelHandler;

	private bannerEnabled: boolean;
	private initialized = false;

	constructor() {
		this.bannerEnabled = !!document.getElementById(
			SWUP_SELECTORS.bannerWrapper.slice(1),
		);

		// 初始化各个处理器
		this.fancyboxHandler = getFancyboxHandler();
		this.backToTopHandler = getBackToTopHandler(this.bannerEnabled);
		this.panelHandler = getPanelHandler();
	}

	/**
	 * 初始化 Swup 管理器
	 */
	async init(): Promise<void> {
		if (this.initialized) {
			return;
		}

		const transitionEffect = getTransitionEffect();
		transitionEffect.applyConfig();

		await this.initPanelHandler();

		// 设置 Sakura 特效
		this.setupSakura();

		// 初始化 Swup 钩子
		this.initSwupHooks();

		// 初始化返回顶部处理器
		initBackToTopHandler(this.bannerEnabled);

		// 初始化 Banner
		this.initBanner();

		// 初始化链接预加载
		this.initPreloading();

		this.initialized = true;
		console.log("SwupManager: 初始化完成");
	}

	/**
	 * 初始化面板处理器
	 */
	private async initPanelHandler(): Promise<void> {
		try {
			await initPanelHandler();
		} catch (error) {
			console.error("SwupManager: 面板处理器初始化失败", error);
		}
	}

	/**
	 * 设置 Sakura 特效
	 */
	private setupSakura(): void {
		setupSakuraOnDOMReady(widgetConfigs);
	}

	/**
	 * 初始化 Swup 钩子
	 */
	private initSwupHooks(): void {
		// 创建钩子管理器
		this.hooksManager = new SwupHooksManager(this.bannerEnabled, {
			showBanner: this.showBanner.bind(this),
			initFancybox: async () => {
				await initFancybox();
			},
			cleanupFancybox: () => {
				cleanupFancybox();
			},
			initCustomScrollbar: () => {
				initCustomScrollbar();
			},
			checkKatex: () => {
				checkKatex();
			},
		});

		// 如果 Swup 已经就绪，直接设置钩子
		if (window?.swup?.hooks) {
			initFancybox();
			checkKatex();
			this.hooksManager.registerHooks();
		} else {
			// 监听 Swup 就绪事件
			document.addEventListener("swup:enable", () => {
				if (this.hooksManager) {
					this.hooksManager.registerHooks();
				}
			});

			// 监听 DOM 加载（确保首屏也能加载优化组件）
			if (document.readyState === "loading") {
				document.addEventListener("DOMContentLoaded", async () => {
					await initFancybox();
					checkKatex();
				});
			} else {
				initFancybox();
				checkKatex();
			}
		}
	}

	/**
	 * 初始化 Banner
	 */
	private initBanner(): void {
		if (document.readyState === "loading") {
			document.addEventListener("DOMContentLoaded", async () => {
				this.showBanner();
			});
		} else {
			this.showBanner();
		}
	}

	/**
	 * 初始化链接预加载
	 */
	private initPreloading(): void {
		if (document.readyState === "loading") {
			document.addEventListener("DOMContentLoaded", () => {
				initLinkPreloading();
			});
		} else {
			initLinkPreloading();
		}
	}

	/**
	 * 显示 Banner
	 * 轮播图由 Banner.astro 中的内联脚本自行初始化（data-swup-ignore-script），
	 * 此处仅处理单图模式的淡入效果。
	 */
	showBanner(): void {
		requestAnimationFrame(() => {
			// 处理单图 Banner (桌面端)
			const banner = document.getElementById(
				SWUP_SELECTORS.banner.slice(1),
			);
			if (banner) {
				banner.classList.remove("opacity-0", "scale-105");
			}

			// 处理移动端单图 Banner
			const mobileBanner = document.querySelector(
				'.block.md\\:hidden[alt="Mobile banner image of the blog"]',
			);
			if (mobileBanner && !document.getElementById("banner-carousel")) {
				mobileBanner.classList.remove("opacity-0", "scale-105");
				mobileBanner.classList.add("opacity-100");
			}
		});
	}

	/**
	 * 销毁管理器
	 */
	destroy(): void {
		this.hooksManager = null;
		this.fancyboxHandler.destroy();
		this.backToTopHandler.destroy();
		this.panelHandler.destroy();
		destroyTransitionEffect();
		this.initialized = false;
	}

	/**
	 * 获取 Banner 启用状态
	 */
	isBannerEnabled(): boolean {
		return this.bannerEnabled;
	}
}

// 创建全局实例
let globalSwupManager: SwupManager | null = null;

/**
 * 获取全局 Swup 管理器实例
 */
export function getSwupManager(): SwupManager {
	if (!globalSwupManager) {
		globalSwupManager = new SwupManager();
	}
	return globalSwupManager;
}

/**
 * 初始化 Swup 管理器（便捷函数）
 */
export async function initSwupManager(): Promise<void> {
	const manager = getSwupManager();
	await manager.init();
}

import type { AlbumGroup, Photo } from "../types/album";

// 使用 import.meta.glob 替代 fs，支持 Cloudflare Workers
const albumModules = import.meta.glob<{ default: Record<string, any> }>(
	"/public/images/albums/*/info.json",
	{ eager: true }
);

// 获取所有相册图片
const imageModules = import.meta.glob<ImageMetadata>(
	"/public/images/albums/**/*.{jpg,jpeg,png,gif,webp}",
	{ eager: true, import: "default" }
);

export async function scanAlbums(): Promise<AlbumGroup[]> {
	const albums: AlbumGroup[] = [];

	// 处理每个相册
	for (const [path, module] of Object.entries(albumModules)) {
		// 从路径中提取相册文件夹名
		const match = path.match(/\/public\/images\/albums\/([^/]+)\/info\.json$/);
		if (!match) {continue;}

		const folderName = match[1];
		const album = await processAlbumFolder(folderName, module.default);
		if (album) {
			albums.push(album);
		}
	}

	// 按日期排序
	albums.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

	return albums;
}

async function processAlbumFolder(
	folderName: string,
	info: Record<string, any>
): Promise<AlbumGroup | null> {
	// 检查是否为外链模式
	const isExternalMode = info.mode === "external";
	let photos: Photo[] = [];
	let cover: string;

	if (isExternalMode) {
		// 外链模式：从 info.json 中获取封面和照片
		if (!info.cover) {
			console.warn(`相册 ${folderName} 外链模式缺少 cover 字段`);
			return null;
		}

		cover = info.cover;
		photos = processExternalPhotos(info.photos || [], folderName);
	} else {
		// 本地模式：从 import.meta.glob 结果中获取图片
		const albumImages = Object.entries(imageModules).filter(([path]) =>
			path.includes(`/public/images/albums/${folderName}/`)
		);

		// 查找封面
		const coverEntry = albumImages.find(([path]) =>
			path.endsWith("cover.webp") || path.endsWith("cover.jpg")
		);

		if (!coverEntry) {
			console.warn(`相册 ${folderName} 缺少 cover 文件`);
			return null;
		}

		const coverPath = coverEntry[0];
		cover = coverPath.includes("cover.webp")
			? `/images/albums/${folderName}/cover.webp`
			: `/images/albums/${folderName}/cover.jpg`;

		photos = scanPhotos(albumImages, folderName);
	}

	// 检查是否隐藏相册
	if (info.hidden === true) {
		console.log(`相册 ${folderName} 已设置为隐藏，跳过显示`);
		return null;
	}

	// 构建相册对象
	return {
		id: folderName,
		title: info.title || folderName,
		description: info.description || "",
		cover,
		date: info.date || new Date().toISOString().split("T")[0],
		location: info.location || "",
		tags: info.tags || [],
		photos,
	};
}

function scanPhotos(
	albumImages: [string, ImageMetadata][],
	albumId: string
): Photo[] {
	const photos: Photo[] = [];

	// 过滤掉封面文件
	const imageFiles = albumImages.filter(([path]) => {
		const fileName = path.split("/").pop();
		return fileName && fileName !== "cover.webp" && fileName !== "cover.jpg";
	});

	// 创建 WebP 映射
	const fileWebpMap = new Map<string, string>();
	for (const [path] of imageFiles) {
		const fileName = path.split("/").pop() || "";
		const baseName = fileName.replace(/\.(jpg|jpeg|png|gif|webp)$/i, "");
		const ext = fileName.split(".").pop()?.toLowerCase();

		if (ext === "jpg" || ext === "jpeg" || ext === "png") {
			const webpPath = path.replace(/\.(jpg|jpeg|png)$/i, ".webp");
			if (imageFiles.some(([p]) => p === webpPath)) {
				fileWebpMap.set(fileName, baseName + ".webp");
			}
		}
	}

	imageFiles.forEach(([path], index) => {
		const fileName = path.split("/").pop() || "";
		const { baseName, tags } = parseFileName(fileName);

		const src = fileWebpMap.has(fileName)
			? `/images/albums/${albumId}/${fileWebpMap.get(fileName)}`
			: `/images/albums/${albumId}/${fileName}`;

		photos.push({
			id: `${albumId}-photo-${index}`,
			src,
			alt: baseName,
			title: baseName,
			tags: tags,
			date: new Date().toISOString().split("T")[0], // 使用当前日期，因为无法获取文件 stats
		});
	});

	return photos;
}

function processExternalPhotos(
	externalPhotos: any[],
	albumId: string
): Photo[] {
	const photos: Photo[] = [];

	externalPhotos.forEach((photo, index) => {
		if (!photo.src) {
			console.warn(
				`相册 ${albumId} 的第 ${index + 1} 张照片缺少 src 字段`
			);
			return;
		}

		photos.push({
			id: photo.id || `${albumId}-external-photo-${index}`,
			src: photo.src,
			thumbnail: photo.thumbnail,
			alt: photo.alt || photo.title || `Photo ${index + 1}`,
			title: photo.title,
			description: photo.description,
			tags: photo.tags || [],
			date: photo.date || new Date().toISOString().split("T")[0],
			location: photo.location,
			width: photo.width,
			height: photo.height,
		});
	});

	return photos;
}

function parseFileName(fileName: string): { baseName: string; tags: string[] } {
	// 移除扩展名
	const nameWithoutExt = fileName.replace(/\.(jpg|jpeg|png|gif|webp)$/i, "");

	// 匹配文件名中的标签，格式为：文件名_标签1_标签2.扩展名
	const parts = nameWithoutExt.split("_");

	if (parts.length > 1) {
		// 第一部分作为基本名称，其余部分作为标签
		const baseName = parts.slice(0, -2).join("_");
		const tags = parts.slice(-2);
		return { baseName, tags };
	}

	// 如果没有标签，返回不带扩展名的文件名
	return { baseName: nameWithoutExt, tags: [] };
}

