/**
 * 导航工具函数
 * 提供统一的页面导航功能，支持 Swup 无刷新跳转
 */

/**
 * 导航到指定页面
 * @param url 目标页面URL
 * @param options 导航选项
 */
export function navigateToPage(
	url: string,
	options?: {
		replace?: boolean;
		force?: boolean;
	},
): void {
	// 检查 URL 是否有效
	if (!url || typeof url !== "string") {
		console.warn("navigateToPage: Invalid URL provided");
		return;
	}

	// 检查是否在客户端环境
	if (typeof window === "undefined" || typeof document === "undefined") {
		return;
	}

	// 如果是外部链接，直接跳转
	if (
		url.startsWith("http://") ||
		url.startsWith("https://") ||
		url.startsWith("//")
	) {
		window.open(url, "_blank");
		return;
	}

	// 如果是锚点链接，滚动到对应位置
	if (url.startsWith("#")) {
		const element = document.getElementById(url.slice(1));
		if (element) {
			element.scrollIntoView({ behavior: "smooth" });
		}
		return;
	}

	// 检查 Swup 是否可用
	if ((window as any).swup) {
		try {
			// 使用 Swup 进行无刷新跳转
			if (options?.replace) {
				(window as any).swup.navigate(url, { history: false });
			} else {
				(window as any).swup.navigate(url);
			}
		} catch (error) {
			console.error("Swup navigation failed:", error);
			// 降级到普通跳转
			fallbackNavigation(url, options);
		}
	} else {
		// Swup 不可用时的降级处理
		fallbackNavigation(url, options);
	}
}

/**
 * 降级导航函数
 * 当 Swup 不可用时使用普通的页面跳转
 */
function fallbackNavigation(
	url: string,
	options?: {
		replace?: boolean;
		force?: boolean;
	},
): void {
	if (typeof window === "undefined") {
		return;
	}
	if (options?.replace) {
		window.location.replace(url);
	} else {
		window.location.href = url;
	}
}

/**
 * 检查 Swup 是否已准备就绪
 */
export function isSwupReady(): boolean {
	return typeof window !== "undefined" && !!(window as any).swup;
}

/**
 * 等待 Swup 准备就绪
 * @param timeout 超时时间（毫秒）
 */
export function waitForSwup(timeout = 5000): Promise<boolean> {
	if (typeof window === "undefined" || typeof document === "undefined") {
		return Promise.resolve(false);
	}

	return new Promise((resolve) => {
		if (isSwupReady()) {
			resolve(true);
			return;
		}

		let timeoutId: NodeJS.Timeout;

		const checkSwup = () => {
			if (isSwupReady()) {
				clearTimeout(timeoutId);
				document.removeEventListener("swup:enable", checkSwup);
				resolve(true);
			}
		};

		// 监听 Swup 启用事件
		document.addEventListener("swup:enable", checkSwup);

		// 设置超时
		timeoutId = setTimeout(() => {
			document.removeEventListener("swup:enable", checkSwup);
			resolve(false);
		}, timeout);
	});
}

/**
 * 预加载页面
 * @param url 要预加载的页面URL
 */
export function preloadPage(url: string): void {
	if (!url || typeof url !== "string") {
		return;
	}

	// 如果 Swup 可用，使用其预加载功能
	if (isSwupReady() && (window as any).swup.preload) {
		try {
			(window as any).swup.preload(url);
		} catch (error) {
			console.warn("Failed to preload page:", error);
		}
	}
}

/**
 * 检查是否为同源链接
 */
function isSameOrigin(url: string): boolean {
	if (typeof window === "undefined") {
		return false;
	}
	try {
		const parsed = new URL(url, window.location.origin);
		return parsed.origin === window.location.origin;
	} catch {
		return false;
	}
}

/**
 * 检查网络状态是否为慢速连接
 */
function isSlowConnection(): boolean {
	if (typeof navigator === "undefined") {
		return false;
	}
	const conn = (navigator as any).connection;
	if (!conn) {
		return false;
	}
	return conn.effectiveType === "2g" || conn.effectiveType === "slow-2g";
}

/**
 * 初始化链接预加载功能
 * 使用 IntersectionObserver 观察视口内的链接，在进入视野时预加载
 */
export function initLinkPreloading(): void {
	// 检查是否在客户端环境
	if (typeof window === "undefined" || typeof document === "undefined") {
		return;
	}

	// 如果 Swup 不可用或用户偏好减少动画，不进行预加载
	if (!isSwupReady() || isSlowConnection()) {
		return;
	}

	// 检查用户是否偏好减少动画
	if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
		return;
	}

	// 已预加载的 URL 集合，避免重复预加载
	const preloadedUrls = new Set<string>();

	const observer = new IntersectionObserver(
		(entries) => {
			entries.forEach((entry) => {
				if (entry.isIntersecting) {
					const link = entry.target as HTMLAnchorElement;
					const href = link.href;

					// 检查是否有效、是否同源、是否已预加载、是否当前页面
					if (
						href &&
						isSameOrigin(href) &&
						!preloadedUrls.has(href) &&
						href !== window.location.href &&
						!href.includes("#")
					) {
						preloadedUrls.add(href);

						// 使用 requestIdleCallback 在空闲时预加载
						if ("requestIdleCallback" in window) {
							requestIdleCallback(() => preloadPage(href), {
								timeout: 2000,
							});
						} else {
							setTimeout(() => preloadPage(href), 100);
						}
					}
				}
			});
		},
		{
			rootMargin: "200px",
		},
	);

	// 观察所有内部链接
	const observeLinks = () => {
		document
			.querySelectorAll('a[href^="/"], a[href^="./"], a[href^="../"]')
			.forEach((link) => {
				observer.observe(link);
			});
	};

	// 初始观察
	observeLinks();

	// 页面切换后重新观察（Swup 会替换 main 容器内容）
	const mainContainer = document.querySelector("main");
	if (mainContainer) {
		const mutationObserver = new MutationObserver(() => {
			observeLinks();
		});
		mutationObserver.observe(mainContainer, {
			childList: true,
			subtree: true,
		});
	}
}

/**
 * 获取当前页面路径
 */
export function getCurrentPath(): string {
	return typeof window !== "undefined" ? window.location.pathname : "";
}

/**
 * 检查是否为首页
 */
export function isHomePage(): boolean {
	const path = getCurrentPath();
	return path === "/" || path === "";
}

/**
 * 检查是否为文章页面
 */
export function isPostPage(): boolean {
	const path = getCurrentPath();
	return path.startsWith("/posts/");
}

/**
 * 检查两个路径是否相等
 */
export function pathsEqual(path1: string, path2: string): boolean {
	// 标准化路径（移除末尾斜杠）
	const normalize = (path: string) => {
		return path.endsWith("/") && path.length > 1 ? path.slice(0, -1) : path;
	};

	return normalize(path1) === normalize(path2);
}

/**
 * 统一的浮窗管理器
 * 确保同一时间只有一个浮窗处于打开状态，并提供统一的动画效果
 */

type PanelId =
	| "mobile-toc-panel"
	| "display-setting"
	| "nav-menu-panel"
	| "search-panel"
	| "wallpaper-mode-panel";

class PanelManager {
	private activePanels = new Set<PanelId>();
	private panelStack: PanelId[] = [];
	private readonly duration = 100;

	/**
	 * 应用动画打开浮窗
	 */
	private animateIn(panel: HTMLElement): Promise<void> {
		return new Promise((resolve) => {
			// 检查是否正在主题切换，如果是则跳过动画
			const isThemeTransitioning =
				document.documentElement.classList.contains(
					"is-theme-transitioning",
				);

			if (isThemeTransitioning) {
				// 主题切换期间，直接显示面板，不设置pointer-events: none
				panel.classList.remove("float-panel-closed");
				panel.style.opacity = "1";
				panel.style.transform = "scale(1) translateY(0)";
				resolve();
				return;
			}

			panel.classList.remove("float-panel-closed");
			panel.style.opacity = "0";
			panel.style.transform = "scale(0.95) translateY(-10px)";
			panel.style.pointerEvents = "none";

			requestAnimationFrame(() => {
				panel.style.transition = `all ${this.duration}ms ease-out`;

				requestAnimationFrame(() => {
					panel.style.opacity = "1";
					panel.style.transform = "scale(1) translateY(0)";
					panel.style.pointerEvents = "auto";

					setTimeout(() => {
						panel.style.transition = "";
						resolve();
					}, this.duration);
				});
			});
		});
	}

	/**
	 * 应用动画关闭浮窗
	 */
	private animateOut(panel: HTMLElement): Promise<void> {
		return new Promise((resolve) => {
			// 检查是否正在主题切换
			const isThemeTransitioning =
				document.documentElement.classList.contains(
					"is-theme-transitioning",
				);

			if (isThemeTransitioning) {
				// 主题切换期间，直接关闭面板，不设置pointer-events: none
				panel.classList.add("float-panel-closed");
				panel.style.opacity = "";
				panel.style.transform = "";
				resolve();
				return;
			}

			panel.style.transition = `all ${this.duration}ms ease-out`;
			panel.style.pointerEvents = "none";
			panel.style.opacity = "0";
			panel.style.transform = "scale(0.95) translateY(-10px)";

			setTimeout(() => {
				panel.classList.add("float-panel-closed");
				panel.style.transition = "";
				panel.style.opacity = "";
				panel.style.transform = "";
				panel.style.pointerEvents = "";
				resolve();
			}, this.duration);
		});
	}

	/**
	 * 切换指定浮窗的开关状态
	 * @param panelId 浮窗ID
	 * @param forceState 强制设置状态 (可选)
	 * @returns 浮窗最终状态 (true: 打开, false: 关闭)
	 */
	async togglePanel(
		panelId: PanelId,
		forceState?: boolean,
	): Promise<boolean> {
		const panel = document.getElementById(panelId);
		if (!panel) {
			console.warn(`Panel ${panelId} not found`);
			return false;
		}

		const isClosed = panel.classList.contains("float-panel-closed");
		const shouldOpen = forceState !== undefined ? forceState : isClosed;

		if (shouldOpen) {
			await this.closeAllPanelsExcept(panelId);
			await this.animateIn(panel);
			this.activePanels.add(panelId);
			this.panelStack = this.panelStack.filter((id) => id !== panelId);
			this.panelStack.push(panelId);
			return true;
		}
		await this.closePanel(panelId);
		return false;
	}

	/**
	 * 关闭指定浮窗
	 * @param panelId 浮窗ID
	 */
	async closePanel(panelId: PanelId): Promise<void> {
		const panel = document.getElementById(panelId);
		if (panel && !panel.classList.contains("float-panel-closed")) {
			await this.animateOut(panel);
			this.activePanels.delete(panelId);
			this.panelStack = this.panelStack.filter((id) => id !== panelId);
		}
	}

	/**
	 * 关闭指定浮窗外的所有浮窗
	 * @param exceptPanelId 要保持打开的浮窗ID
	 */
	async closeAllPanelsExcept(exceptPanelId?: PanelId): Promise<void> {
		const closingPromises = Array.from(this.activePanels)
			.filter((panelId) => panelId !== exceptPanelId)
			.map((panelId) => this.closePanel(panelId));

		await Promise.all(closingPromises);
	}
}

